    async function runSearch() {
      const query = state.query.trim()
      const seq = ++searchSeq
      if (query === '') {
        state.server = { sessions: [], prompts: [], tools: [], panels: [] }
        state.error = ''
        state.loading = false
        render()
        return
      }
      // 取消上一个仍在途的请求，避免服务器端堆积扫描
      activeCtl?.abort()
      const controller = new AbortController()
      activeCtl = controller
      // 最少 2 个字符才发起查询（按码点计，CJK 单字不触发全量扫描）
      if ([...query].length < 2) {
        state.server = { sessions: [], prompts: [], tools: [], panels: [] }
        state.error = ''
        state.loading = false
        render()
        return
      }
      state.loading = true
      state.error = ''
      render()
      try {
        const data = await api('/api/dsh-search/query?q=' + encodeURIComponent(query), controller.signal)
        if (seq !== searchSeq) return
        state.server = {
          sessions: data.sessions || [],
          prompts: data.prompts || [],
          tools: data.tools || [],
          panels: data.panels || [],
        }
      } catch (error) {
        if (seq !== searchSeq) return
        if (error && error.name === 'AbortError') return
        state.error = error.message || String(error)
        state.server = { sessions: [], prompts: [], tools: [], panels: [] }
      } finally {
        if (seq === searchSeq) {
          state.loading = false
          render()
        }
      }
    }

    /* ================================ 面板开关 ================================ */
```

