      "content": "{\n  \"name\": \"@hyzyn/dsh-search\",\n  \"version\": \"0.4.18\",\n  \"description\": \"DSH Web GUI 的全局搜索插件：侧边栏「全局搜索」（⌘/Ctrl + K）命令面板式一处检索历史会话、Prompt、MCP 工具与设置面板。\",\n  \"type\": \"module\",\n  \"engines\": {\n    \"node\": \">=22.19.0\"\n  },\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": \"./client.js\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"dsh\": {\n    \"manifestVersion\": 1,\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"engines\": {\n      \"dsh\": \">=0.1.7-rc.2\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"sessions\"\n      ]\n    }\n  },\n  \"dependencies\": {\n    \"@hyzyn/dsh-kit\": \"0.8.0\",\n    \"js-yaml\": \"^4.1.0\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.4\",\n    \"@types/node\": \"^22.20.0\",\n    \"typescript\": \"~5.9.3\"\n  },\n  \"scripts\": {\n    \"build\": \"tsc -p tsconfig.json\",\n    \"smoke\": \"node scripts/route-smoke.mjs\",\n    \"preview\": \"node scripts/preview.mjs\",\n    \"typecheck\": \"tsc --noEmit && node ../../scripts/client-lint.mjs\",\n    \"lint:client\": \"node ../../scripts/client-lint.mjs\"\n  },\n  \"files\": [\n    \"lib\",\n    \"client.js\",\n    \"cordis.patch.yml\",\n    \"README.md\"\n  ],\n  \"license\": \"Apache-2.0\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/hyzyn/dsh-plugin-kit.git\",\n    \"directory\": \"packages/search\"\n  },\n  \"homepage\": \"https://github.com/hyzyn/dsh-plugin-kit/tree/main/packages/search#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/hyzyn/dsh-plugin-kit/issues\"\n  },\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/dsh\": \"^0.1.7-rc.2 || ^0.2.0-rc.1 || ^0.2.0-rc.2 || ^0.2.1-alpha.