      "path": "packages/search/src/index.ts",
      "content": "/**\n * @hyzyn/dsh-search — DSH Web GUI 的全局搜索插件（宿主半体）。\n *\n * 能力：\n * - 在 GUI 侧边栏提供「全局搜索」入口，弹窗内搜索历史会话、Prompt、MCP 工具。\n * - 历史会话走 @deepseek-ai/dsh-session-query 的 full-text search；\n *   Prompt 读取 ~/.dsh/prompts.yml 托管区块；MCP 工具从 ctx.tools.schemas()\n *   枚举 mcp__ 前缀工具。\n *\n * 浏览器半体（./client）通过 /api/dsh-search/query 查询；路由带 loopback-only\n * 信任围栏。\n */\nimport { readFileSync, statSync } from 'node:fs'\nimport { join } from 'node:path'\nimport type { Context } from '@deepseek-ai/cordis'\nimport { definePlugin, dshHome, registerLiteralSection } from '@hyzyn/dsh-kit'\nimport yaml from 'js-yaml'\n\nexport interface Config {\n  /** 关闭整个插件（不注册路由、不注入 GUI）。默认开。 */\n  enabled?: boolean\n  /** 单类结果最大条数。默认 8。 */\n  maxResults?: number\n  /** 是否搜索历史会话。默认 true。 */\n  includeSessions?: boolean\n  /** 是否搜索 Prompt。默认 true。 */\n  includePrompts?: boolean\n  /** 是否搜索 MCP 工具。默认 true。 */\n  includeMcpTools?: boolean\n  /** 是否搜索设置面板（插件配置 → 插件配置）。默认 true。 */\n  includePanels?: boolean\n  /** 是否向 agent 注入插件能力公告。默认开。 */\n  announceToAgent?: boolean\n  /** 会话回退扫描的最大会话数：宿主 FTS 不可用时按会话最近优先截断到此数，上限 500。默认 80。 */\n  maxScanSessions?: number\n}\n\nconst promptFilePath = () => process.env.DSH_PROMPT_FILE?.trim() || join(dshHome(), 'prompts.yml')\n\n/* ------------------------------------------------------------------ *\n * Prompt 读取（与 dsh-prompt 共用同一托管文件，只读不改）\n * ------------------------------------------------------------------ */\n\ninterface PromptVersion {\n  id: string\n  label?: string\n  note?: string\n  content: string\n  createdAt: string\n}\n\ninterface Prompt {\n  id: string\n  name: string\n  description?: string\n  versions: PromptVersion[]\n  activeVersionId: string | null\n  ab: { enabled: boolean; aVersionId: string; bVersionId: string; aWeight: number }\n  updatedAt: string\n}\n\ninterface PromptStore {\n  activePromptId: string | null\n  prompts: Prompt[]\n}\n\ninterface ManagedRead {\n  store: PromptStore\n  fileError?: string\n  file: string\n}\n\nfunction emptyStore(): PromptStore {\n  return { activePromptId: null, prompts: [] }\n}\n\n/**\n * 托管文件解析缓存（P1 优化：单文件，无容量上限）：\n * 以文件路径 + (mtimeMs, size) 为 key 复用整个 ManagedRead（含 fileError），\n * 文件未变化时不再 readFileSync + yaml.load；文件不存在（含 statSync 抛错）\n * 也缓存该状态，避免每次 existsSync。\n */\nlet promptStoreCache: { key: string; value: ManagedRead } | undefined\n\n/** 文件指纹：mtimeMs + size；文件不存在或 statSync 失败返回 undefined（按不存在处理）。 */\nfunction promptFileFingerprint(file: string): string | undefined {\n  try {\n    const stat = statSync(file)\n    return stat.mtimeMs + ':' + stat.size\n  } catch {\n    return undefined\n  }\n}\n\nfunction readPromptStore(): ManagedRead {\n  const file = promptFilePath()\n  const fingerprint = promptFileFingerprint(file)\n  const key = file + '|' + (fingerprint ?? 'missing')\n  const cached = promptStoreCache\n  if (cached !== undefined && cached.key === key) return cached.value\n  const result = parsePromptStore(file, fingerprint !== undefined)\n  promptStoreCache = { key, value: result }\n  return result\n}\n\n/** 解析托管区块（不做缓存）；existed 为 false 时按空文件处理。 */\nfunction parsePromptStore(file: string, existed: boolean): ManagedRead {\n  const text = existed ? readFileSync(file, 'utf8') : ''\n  const lines = text.split('\\n')\n  const start = lines.findIndex((line) => line.includes('dsh-prompt-manager managed'))\n  const result: ManagedRead = { store: emptyStore(), file }\n  if (start === -1) return result\n  const end = lines.findIndex((line, index) => index > start && line.includes('end dsh-prompt-manager managed'))\n  if (end === -1) {\n    result.fileError = '托管区块缺少结束标记（# --- end dsh-prompt-manager managed ---）'\n    return result\n  }\n  const block = lines.slice(start + 1, end).join('\\n')\n  if (block.trim() === '' || block.split('\\n').every((line) => line.trim() === '' || line.trim().startsWith('#'))) return result\n  try {\n    const parsed = yaml.load(block) as Partial<PromptStore> | null\n    if (typeof parsed !== 'object' || parsed === null) {\n      result.fileError = '托管区块不是 YAML 对象'\n      return result\n    }\n    const prompts = (Array.isArray(parsed.prompts) ? parsed.prompts : []).flatMap((item) => {\n      if (typeof item !== 'object' || item === null) return []\n      const raw = item as Partial<Prompt>\n      const versions = Array.isArray(raw.versions) ? (raw.versions as PromptVersion[]) : []\n      const rawAb = raw.ab as Partial<Prompt['ab']> | undefined\n      return [{\n        ...raw,\n        versions,\n        activeVersionId: typeof raw.activeVersionId === 'string' ? raw.activeVersionId : null,\n        ab: {\n          enabled: rawAb?.enabled === true,\n          aVersionId: typeof rawAb?.aVersionId === 'string' ? rawAb.aVersionId : (versions[0]?.id ?? ''),\n          bVersionId: typeof rawAb?.bVersionId === 'string' ? rawAb.bVersionId : (versions[versions.length - 1]?.id ?? ''),\n          aWeight: typeof rawAb?.aWeight === 'number' ? rawAb.aWeight : 50,\n        },\n      } as Prompt]\n    })\n    result.store = {\n      activePromptId: typeof parsed.activePromptId === 'string' ? parsed.activePromptId : null,\n      prompts,\n    }\n  } catch (error) {\n    result.fileError = '托管区块解析失败: ' + (error instanceof Error ? error.message : String(error))\n  }\n  return result\n}\n\n/* ------------------------------------------------------------------ *\n * 搜索逻辑\n * ------------------------------------------------------------------ */\n\nfunction normalizeQuery(raw: string): string {\n  return raw.trim().toLowerCase()\n}\n\nfunction includesText(haystack: string | undefined, query: string): boolean {\n  if (!haystack) return false\n  return haystack.toLowerCase().includes(query)\n}\n\nexport function makeSnippet(text: string, query: string, radius = 60): string {\n  const lower = text.toLowerCase()\n  // 多词查询与服务端正则一致按空白切分（正则把空格编译为 \\s+）；单词查询即单词组。\n  const terms = query.trim().split(/\\s+/u).filter((term) => term !== '')\n  const found = terms\n    .map((term) => ({ start: lower.indexOf(term), length: term.length }))\n    .filter((item) => item.start !== -1)\n  if (found.length === 0) return text.slice(0, radius * 2) + (text.length > radius * 2 ? '…' : '')\n  let start: number\n  let end: number\n  if (found.length === terms.length) {\n    // 全部命中：窗口覆盖从最小起点到最大终点，两端各向外扩 40 字符，总长截到 240 字符。\n    const rawStart = Math.min(...found.map((item) => item.start))\n    const rawEnd = Math.max(...found.map((item) => item.start + item.length))\n    start = Math.max(0, rawStart - 40)\n    end = Math.min(text.length, rawEnd + 40, start + 240)\n  } else {\n    // 部分命中：以第一个命中的词为锚，沿用单词 radius 窗口语义。\n    const anchor = found[0]\n    start = Math.max(0, anchor.start - radius)\n    end = Math.min(text.length, anchor.start + anchor.length + radius)\n  }\n  return (start > 0 ? '…' : '') + text.slice(start, end).replace(/\\s+/g, ' ').trim() + (end < text.length ? '…' : '')\n}\n\ninterface PromptHit {\n  id: string\n  name: string\n  description?: string\n  snippet: string\n  active: boolean\n}\n\nfunction searchPrompts(rawQuery: string, limit: number): PromptHit[] {\n  const query = normalizeQuery(rawQuery)\n  if (query === '') return []\n  const managed = readPromptStore()\n  const hits: PromptHit[] = []\n  for (const prompt of managed.store.prompts) {\n    if (hits.length >= limit) break\n    const nameHit = includesText(prompt.name, query)\n    const descriptionHit = includesText(prompt.description, query)\n    const version = prompt.versions.find((item) =>\n      includesText(item.content, query) || includesText(item.label, query) || includesText(item.note, query),\n    )\n    if (!nameHit && !descriptionHit && version === undefined) continue\n    const snippet = version !== undefined\n      ? makeSnippet(version.content, query)\n      : (prompt.description ?? prompt.name)\n    hits.push({\n      id: prompt.id,\n      name: prompt.name,\n      ...(prompt.description !== undefined ? { description: prompt.description } : {}),\n      snippet,\n      active: prompt.id === managed.store.activePromptId,\n    })\n  }\n  return hits\n}\n\ninterface SessionHit {\n  id: string\n  snippet: string\n  time: number\n}\n\nexport interface SessionQueryLike {\n  searchSessions?(request: {\n    query: string\n    eventFilters?: unknown[]\n    limit?: number\n  }, exec?: { signal?: AbortSignal }): Promise<{ items?: Array<{ header?: { id?: string }; bestMatch?: { snippet?: string; time?: number } }> }>\n  listSessions?(signal?: AbortSignal): Promise<Array<{ header: { id: string } }>>\n  filterEvents?(sessionId: string, filters: unknown[]): Promise<Array<{ text: string; time: number; type?: string; surface?: string }>>\n}\n\nconst MAX_SCAN_SESSIONS = 80\nconst SESSION_SCAN_CONCURRENCY = 6\n// 冷扫描（逐会话解压）单会话约 100-300ms，5s 只够覆盖 ~30 个会话，首个查询\n// 容易被截断成空结果；10s 配合文档缓存预热（超时后后台扫描继续填缓存）\n// 让重试很快收敛。\nconst SCAN_TIMEOUT_MS = 10_000\nconst TEXT_CACHE_TTL_MS = 90_000\nconst TEXT_CACHE_MAX_BYTES = 192 * 1024 * 1024\nconst RESULT_CACHE_TTL_MS = 30_000\nconst RESULT_CACHE_MAX_ENTRIES = 64\nlet warnedSearchFallback = false\n\n/* ------------------------------------------------------------------ *\n * 会话文档缓存（P0 优化：同一会话只解压一次，90s 内重复查询直接内存扫描）\n * ------------------------------------------------------------------ */\n\ninterface CachedSessionDocs {\n  docs: Array<{ text: string; time: number; type?: string; surface?: string }>\n  bytes: number\n  at: number\n}\n\nconst sessionDocCache = new Map<string, CachedSessionDocs>()\nlet sessionDocBytes = 0\n\nfunction getCachedDocs(sessionId: string): CachedSessionDocs | undefined {\n  const entry = sessionDocCache.get(sessionId)\n  if (entry === undefined) return undefined\n  if (Date.now() - entry.at > TEXT_CACHE_TTL_MS) {\n    sessionDocCache.delete(sessionId)\n    sessionDocBytes -= entry.bytes\n    return undefined\n  }\n  return entry\n}\n\nfunction setCachedDocs(sessionId: string, entry: CachedSessionDocs): void {\n  const previous = sessionDocCache.get(sessionId)\n  if (previous !== undefined) sessionDocBytes -= previous.bytes\n  sessionDocCache.set(sessionId, entry)\n  sessionDocBytes += entry.bytes\n  // LRU 淘汰：超出字节预算时从最旧条目起淘汰\n  while (sessionDocBytes > TEXT_CACHE_MAX_BYTES && sessionDocCache.size > 1) {\n    const oldestKey = sessionDocCache.keys().next().value as string | undefined\n    if (oldestKey === undefined || oldestKey === sessionId) break\n    const oldest = sessionDocCache.get(oldestKey)\n    sessionDocCache.delete(oldestKey)\n    if (oldest !== undefined) sessionDocBytes -= oldest.bytes\n  }\n}\n\n/* ------------------------------------------------------------------ *\n * 结果缓存（P0 优化：相同查询串 30s 内直接复用）\n * ------------------------------------------------------------------ */\n\ninterface CachedSearchResult {\n  hits: SessionHit[]\n  at: number\n}\n\nconst resultCache = new Map<string, CachedSearchResult>()\n\nfunction getCachedResult(key: string): SessionHit[] | undefined {\n  const entry = resultCache.get(key)\n  if (entry === undefined) return undefined\n  if (Date.now() - entry.at > RESULT_CACHE_TTL_MS) {\n    resultCache.delete(key)\n    return undefined\n  }\n  return entry.hits\n}\n\nfunction setCachedResult(key: string, hits: SessionHit[]): void {\n  if (resultCache.size >= RESULT_CACHE_MAX_ENTRIES) {\n    const oldestKey = resultCache.keys().next().value\n    if (oldestKey !== undefined) resultCache.delete(oldestKey)\n  }\n  resultCache.set(key, { hits, at: Date.now() })\n}\n\n/**\n * 生成本地扫描的文本过滤器，语义与宿主 compileSessionTextFilter 对齐：\n * 大小写不敏感、空白弹性、正则元字符转义。\n */\nexport function compileLocalTextFilter(query: string): RegExp {\n  const pattern = query.trim().split(/\\s+/u).map((part) => part.replace(/[.*+?^${}()|[\\]\\\\]/gu, '\\\\$&')).join('\\\\s+')\n  return new RegExp(pattern, 'iu')\n}\n\nasync function searchSessions(ctx: Context, rawQuery: string, limit: number, signal?: AbortSignal, maxScanSessions = MAX_SCAN_SESSIONS): Promise<SessionHit[]> {\n  const query = rawQuery.trim()\n  if (query === '') return []\n  // 1 字符查询（含 CJK 单字）命中面极小却要付出全量扫描成本，直接不搜会话\n  if ([...query].length < 2) return []\n  const sessionQuery = getService(ctx, 'sessionQuery') as SessionQueryLike | undefined\n  if (sessionQuery === undefined) return []\n  const cacheKey = query + '|' + limit\n  const cached = getCachedResult(cacheKey)\n  if (cached !== undefined) return filterVisibleSessionHits(ctx, cached, signal)\n  let hits: SessionHit[] = []\n  if (typeof sessionQuery.searchSessions === 'function') {\n    try {\n      const page = await sessionQuery.searchSessions({\n        query,\n        eventFilters: [\n          { kind: 'type', values: ['user/message', 'assistant/message'] },\n          { kind: 'surface', values: ['current'] },\n        ],\n        limit,\n      }, { signal })\n      hits = (page.items ?? []).slice(0, limit).flatMap((hit) => {\n        const id = hit.header?.id\n        if (!id) return []\n        if (isSubagentHeader(hit.header)) return []\n        return [{\n          id,\n          snippet: hit.bestMatch?.snippet ?? '',\n          time: hit.bestMatch?.time ?? 0,\n        }]\n      })\n      const visible = await filterVisibleSessionHits(ctx, hits, signal)\n      // 空结果不写缓存：回退扫描被超时截断时可能暂时为空，\n      // 缓存会让 30s 内的重试一直为空（后台扫描仍在填充文档缓存）。\n      if (visible.length > 0) setCachedResult(cacheKey, visible)\n      return visible\n    } catch (error) {\n      // openAt: \"never\" 等场景会禁用全文索引；退化为逐会话扫描原始事件。\n      // 这样即使 session search 被禁用，Prompt / MCP 搜索也不会被拖垮。\n      if (!warnedSearchFallback) {\n        warnedSearchFallback = true\n        console.info('[dsh-global-search] session full-text search is disabled (openAt: \"never\"); falling back to per-session scan.')\n      }\n    }\n  }\n  const scanned = await searchSessionsByScan(sessionQuery, query, limit, signal, maxScanSessions)\n  const visible = await filterVisibleSessionHits(ctx, scanned.hits, signal)\n  // 空结果不写缓存（超时截断的空结果会被 30s 固化）——同理，**被切走的非空部分结果**\n  // 也不写：它只是「还没扫完」，缓存会让立刻重试拿到同一份不完整清单（后台扫描仍在\n  // 补文档缓存，不缓存时重试很快就能拿全）。\n  if (!scanned.truncated && visible.length > 0) setCachedResult(cacheKey, visible)\n  return visible\n}\n\n/**\n * 防御式读取会话记录时间（ms）：依次尝试 header 与记录顶层上的\n * time / updatedAt / createdAt / startTime，number 直接用，string 用\n * Date.parse（NaN 视为缺失），取能解析到的最大值；全部缺失返回 undefined。\n */\nexport function readRecordTime(record: unknown): number | undefined {\n  if (typeof record !== 'object' || record === null) return undefined\n  const source = record as { header?: Record<string, unknown> } & Record<string, unknown>\n  const header = typeof source.header === 'object' && source.header !== null ? source.header : {}\n  let best: number | undefined\n  for (const value of [header.time, header.updatedAt, header.createdAt, header.startTime, source.time, source.updatedAt, source.createdAt, source.startTime]) {\n    const parsed = typeof value === 'number' ? value : typeof value === 'string' ? Date.parse(value) : Number.NaN\n    if (!Number.isFinite(parsed)) continue\n    if (best === undefined || parsed > best) best = parsed\n  }\n  return best\n}\n\n/**\n * subagent 会话不能作为主会话打开（sessions.open 只接受主会话或已编目的\n * 子会话地址，直接 open 子会话 id 视图是空白），搜索结果里必须排除。\n */\nexport function isSubagentHeader(header: unknown): boolean {\n  if (typeof header !== 'object' || header === null) return false\n  const source = header as { origin?: unknown; delegationDepth?: unknown }\n  if (source.origin === 'subagent') return true\n  return typeof source.delegationDepth === 'number' && source.delegationDepth > 0\n}\n\n/**\n * 记录按时间降序排列（最近优先）：没有时间的记录排在有时间记录之后并保持原有相对顺序，\n * 有时间记录之间用原索引做稳定 tie-break。\n */\nexport function sortRecordsByTimeDesc<T>(records: T[]): T[] {\n  return records\n    .map((record, index) => ({ record, index, time: readRecordTime(record) }))\n    .sort((a, b) => {\n      if (a.time === undefined && b.time === undefined) return a.index - b.index\n      if (a.time === undefined) return 1\n      if (b.time === undefined) return -1\n      return a.time === b.time ? a.index - b.index : b.time - a.time\n    })\n    .map((entry) => entry.record)\n}\n\n/**\n * 回退扫描（宿主 FTS 不可用时逐会话扫描原始事件）：\n * 会话按最近优先截断到 maxScanSessions；命中结果按时间倒序返回。\n */\nexport async function searchSessionsByScan(\n  sessionQuery: SessionQueryLike,\n  query: string,\n  limit: number,\n  signal?: AbortSignal,\n  maxScanSessions = MAX_SCAN_SESSIONS,\n): Promise<{ hits: SessionHit[]; truncated: boolean }> {\n  if (typeof sessionQuery.listSessions !== 'function' || typeof sessionQuery.filterEvents !== 'function')\n    return { hits: [], truncated: false }\n  let records: Array<{ header: { id: string } }> = []\n  try {\n    records = await sessionQuery.listSessions(signal)\n  } catch (error) {\n    console.warn('[dsh-global-search] session list unavailable for fallback scan:', error instanceof Error ? error.message : String(error))\n    // 会话清单都拿不到：这是「没扫成」，不是「扫完没有命中」——同样按 truncated 处理，\n    // 免得这个空结果被缓存 30s\n    return { hits: [], truncated: true }\n  }\n  const filter = compileLocalTextFilter(query)\n  // subagent 会话排除在扫描之外（打不开，也不占结果名额）；\n  // 最近优先：先按记录时间降序，再截断到 maxScanSessions。\n  const sessions = sortRecordsByTimeDesc(records.filter((record) => !isSubagentHeader(record?.header))).slice(0, maxScanSessions)\n  const collected: SessionHit[] = []\n\n  const scanPromise = (async () => {\n    let next = 0\n    const workers = Array.from({ length: Math.min(SESSION_SCAN_CONCURRENCY, sessions.length) }, async () => {\n      while (next < sessions.length && collected.length < limit) {\n        if (signal?.aborted) return\n        const index = next\n        next += 1\n        const hit = await scanOneSession(sessionQuery, sessions[index].header.id, filter, query)\n        if (hit !== undefined) collected.push(hit)\n      }\n    })\n    await Promise.all(workers)\n  })()\n\n  // 整体超时：返回已收集的部分结果，避免最坏情况长时间无响应；\n  // 即使被切走，后台任务仍在为下一个查询填充会话缓存。\n  let scanTimeout: ReturnType<typeof setTimeout> | undefined\n  // 注意：计时器在竞态构造时就已创建，所以 `scanTimeout !== undefined` 不能用来判断\n  // 「是否被超时切走」——必须由回调自己置标志位\n  let timedOut = false\n  await Promise.race([\n    scanPromise,\n    new Promise<void>((resolve) => {\n      scanTimeout = setTimeout(() => {\n        timedOut = true\n        resolve()\n      }, SCAN_TIMEOUT_MS)\n    }),\n  ])\n  // 扫描先结束时清掉超时定时器：后台扫描不受影响，但不留 ref 计时器拖住进程退出。\n  if (scanTimeout !== undefined) clearTimeout(scanTimeout)\n  // 命中按时间倒序返回（同一时间保持收集顺序稳定）；只影响回退扫描路径，\n  // 宿主 FTS 正常返回时仍保持其相关度排序。\n  collected.sort((a, b) => b.time - a.time)\n  // truncated：这次是**被超时切走的**部分结果，不是扫完了的全部命中。\n  // 调用方据此决定不写缓存——部分结果一旦缓存，立刻重试也拿不到更全的清单。\n  return { hits: collected.slice(0, limit), truncated: timedOut }\n}\n\n/** 单会话扫描：优先使用缓存文档；未缓存则一次拉取全部文档并缓存（消除重复解压）。 */\nasync function scanOneSession(\n  sessionQuery: SessionQueryLike,\n  sessionId: string,\n  filter: RegExp,\n  query: string,\n): Promise<SessionHit | undefined> {\n  try {\n    if (typeof sessionQuery.filterEvents !== 'function') return undefined\n    let cached = getCachedDocs(sessionId)\n    if (cached === undefined) {\n      const docs = await sessionQuery.filterEvents(sessionId, [])\n      let bytes = 0\n      const docsOut = docs.map((doc) => {\n        if (typeof doc.text === 'string') bytes += doc.text.length\n        return {\n          text: doc.text,\n          time: doc.time,\n          ...(doc.type !== undefined ? { type: doc.type } : {}),\n          ...(doc.surface !== undefined ? { surface: doc.surface } : {}),\n        }\n      })\n      cached = { docs: docsOut, bytes, at: Date.now() }\n      setCachedDocs(sessionId, cached)\n    }\n    const doc = cached.docs.find((item) =>\n      filter.test(item.text) && item.surface === 'current' && (item.type === 'user/message' || item.type === 'assistant/message'),\n    ) ?? cached.docs.find((item) => filter.test(item.text))\n    if (doc === undefined) return undefined\n    return {\n      id: sessionId,\n      snippet: makeSnippet(doc.text, query),\n      time: doc.time,\n    }\n  } catch {\n    // 单个会话读取失败不阻塞其它会话\n    return undefined\n  }\n}\n\n/* ------------------------------------------------------------------ *\n * 可见会话集合短缓存（P1 优化：5s 内复用 persistence.list 结果，\n * 结果缓存命中路径 filterVisibleSessionHits 同样受益）\n * ------------------------------------------------------------------ */\n\nconst VISIBLE_CACHE_TTL_MS = 5_000\n/** 缓存的可见会话集合（只读）；空集合不写缓存。 */\nlet visibleSessionIdsCache: { ids: Set<string>; at: number } | undefined\n\nasync function getVisibleSessionIds(ctx: Context, signal?: AbortSignal): Promise<Set<string>> {\n  const cached = visibleSessionIdsCache\n  if (cached !== undefined && Date.now() - cached.at <= VISIBLE_CACHE_TTL_MS) return cached.ids\n  const ids = new Set<string>()\n  const sessions = getService(ctx, 'sessions') as { list?: () => Array<{ id: string }> } | undefined\n  try {\n    for (const session of sessions?.list?.() ?? []) ids.add(session.id)\n  } catch {\n    /* 忽略 live 列表读取失败 */\n  }\n  const persistence = getService(ctx, 'sessionPersistence') as {\n    list?(signal?: AbortSignal): Promise<Array<{ id?: string; cwd?: string; header?: { id?: string; cwd?: string } }>>\n  } | undefined\n  if (persistence?.list !== undefined) {\n    try {\n      const cold = await persistence.list(signal)\n      for (const meta of cold) {\n        // 宿主实际返回快照形状 { header: { id, cwd }, revision, ... }；\n        // 兼容旧的扁平 { id, cwd } 形状。cwd 缺失视为不可跳转，跳过。\n        const header = meta.header\n        if (isSubagentHeader(header) || isSubagentHeader(meta)) continue\n        const id = meta.id ?? header?.id\n        const cwd = meta.cwd ?? header?.cwd\n        if (id !== undefined && cwd !== undefined) ids.add(id)\n      }\n    } catch {\n      /* 忽略持久化列表读取失败 */\n    }\n  }\n  // 空集合不写缓存（下次查询重算），避免新会话上线后被空集缓存挡住。\n  if (ids.size > 0) visibleSessionIdsCache = { ids, at: Date.now() }\n  return ids\n}\n\nasync function filterVisibleSessionHits(ctx: Context, hits: SessionHit[], signal?: AbortSignal): Promise<SessionHit[]> {\n  const visible = await getVisibleSessionIds(ctx, signal)\n  // 拿不到可见会话列表时不再返回可能无法跳转的会话，避免“能搜到但点不开”。\n  if (visible.size === 0) return []\n  return hits.filter((hit) => visible.has(hit.id))\n}\n\ninterface McpToolHit {\n  name: string\n  description: string\n}\n\nfunction searchMcpTools(ctx: Context, rawQuery: string, limit: number): McpToolHit[] {\n  const query = normalizeQuery(rawQuery)\n  if (query === '') return []\n  const tools = getService(ctx, 'tools') as {\n    schemas?(scope?: unknown): Array<{ name: string; description?: string }>\n  } | undefined\n  if (tools?.schemas === undefined) return []\n  const schemas = tools.schemas()\n  const hits: McpToolHit[] = []\n  for (const schema of schemas) {\n    if (hits.length >= limit) break\n    if (!schema.name.startsWith('mcp__')) continue\n    if (!includesText(schema.name, query) && !includesText(schema.description, query)) continue\n    hits.push({ name: schema.name, description: schema.description ?? '' })\n  }\n  return hits\n}\n\n/* ------------------------------------------------------------------ *\n * 设置面板搜索（插件配置 → 插件配置 里的可配置卡片）\n * ------------------------------------------------------------------ */\n\ninterface PanelDefinition {\n  id: string\n  /** section: 设置窗口一级大类（导航级）；card: 插件配置卡片 */\n  kind: 'section' | 'card'\n  /** 标题（中英，按 openSettingsSection/openSettingsCard 的 titleTexts 匹配顺序） */\n  titles: string[]\n  /** 额外可搜索关键词（含标题别名） */\n  keywords: string[]\n  description: string\n  /** 宿主插件的 registry name；为 undefined 表示随 DSH 内置、恒可用（官方大类/卡片） */\n  registryName?: string\n}\n\n/** 内置设置面板目录：设置一级大类 + 官方面板 + dsh-plugin-kit 各插件面板。 */\nconst PANEL_DIRECTORY: PanelDefinition[] = [\n  // 设置窗口一级大类（导航级）\n  {\n    id: 's-general',\n    kind: 'section',\n    titles: ['通用设置', 'General'],\n    keywords: ['general', '通用', '设置', '常规', '基础'],\n    description: '界面与工具的通用选项',\n  },\n  {\n    id: 's-models',\n    kind: 'section',\n    titles: ['模型', 'Models'],\n    keywords: ['model', 'models', '模型', '提供商', 'provider', '推理'],\n    description: '模型提供商与模型列表管理',\n  },\n  {\n    id: 's-plugins',\n    kind: 'section',\n    titles: ['插件', 'Plugins'],\n    keywords: ['plugin', 'plugins', '插件', '扩展'],\n    description: '插件配置与插件清单',\n  },\n  {\n    id: 's-agent-presets',\n    kind: 'section',\n    titles: ['Agent 预设', 'Agent presets'],\n    keywords: ['agent', 'preset', '预设', 'agent preset', 'agentpresets'],\n    description: '预设方案与角色模板',\n  },\n  {\n    id: 's-market',\n    kind: 'section',\n    titles: ['插件市场', 'Plugin Market'],\n    keywords: ['market', 'marketplace', '插件市场', '市场', '商店', 'plugin market'],\n    description: '发现与安装社区插件',\n  },\n  // 插件配置卡片（随 DSH 内置）\n  {\n    id: 'terminal',\n    kind: 'card',\n    titles: ['终端', 'Shell'],\n    keywords: ['terminal', 'bash', '终端', 'shell', '命令行'],\n    description: 'Shell 行为与命令超时设置',\n  },\n  {\n    id: 'agent-loop',\n    kind: 'card',\n    titles: ['Agent 循环', 'Agent loop'],\n    keywords: ['agent', 'loop', '循环', 'agent loop', 'agentloop'],\n    description: '循环轮次、中断与并发设置',\n  },\n  {\n    id: 'web-search',\n    kind: 'card',\n    titles: ['网页搜索', 'Web search'],\n    keywords: ['web', 'search', '网页', '搜索', 'websearch'],\n    description: '搜索提供商与结果条数',\n  },\n  {\n    id: 'mcp-config',\n    kind: 'card',\n    titles: ['MCP 服务器配置', 'MCP Server Configuration'],\n    keywords: ['mcp', 'server', '服务器', '配置', '工具', '工具集'],\n    description: 'stdio 本地进程或 streamable-http 远程服务',\n    registryName: 'mcp-config',\n  },\n  {\n    id: 'prompt-manager',\n    kind: 'card',\n    titles: ['Prompt 管理', 'Prompt Management'],\n    keywords: ['prompt', 'systemprompt', '提示词', '提示', 'prompts', 'system prompt'],\n    description: 'systemPrompt 可视化编辑、版本管理与 A/B 测试',\n    registryName: 'prompt-manager',\n  },\n  {\n    id: 'env-manager',\n    kind: 'card',\n    titles: ['环境变量 / 密钥管理', 'Environment Variables / Secrets'],\n    keywords: ['env', 'environment', '环境变量', '密钥', 'secret', 'secrets', '环境'],\n    description: '配置进程环境变量与敏感信息',\n    registryName: 'env-manager',\n  },\n  {\n    id: 'profile-manager',\n    kind: 'card',\n    titles: ['Profile 管理', 'Profile Management'],\n    keywords: ['profile', 'profiles', '环境', '配置', '多环境', 'profile 管理'],\n    description: 'DSH profile 的创建、复制、重命名与删除',\n    registryName: 'profile-manager',\n  },\n  {\n    id: 'rss-digest',\n    kind: 'card',\n    titles: ['RSS / 新闻聚合', 'RSS / News Aggregation'],\n    keywords: ['rss', 'news', '新闻', '聚合', 'digest', '今日值得读'],\n    description: '多源订阅与每日「今日值得读」自动摘要',\n    registryName: 'rss-digest',\n  },\n  {\n    id: 'codegraph',\n    kind: 'card',\n    titles: ['Codegraph 集成', 'Codegraph Integration'],\n    keywords: ['codegraph', '代码图谱', '图谱', '索引', '调用链', '影响面', 'code graph'],\n    description: '代码图谱索引、符号搜索与调用链分析',\n    registryName: 'codegraph',\n  },\n  // 补漏（真机测出来的）：目录里六个插件卡片都有 registryName 门禁，唯独漏了 docker，\n  // 于是「全局搜索」里搜 Docker 找不到那张卡片 —— 而插件确实装了（settings 命名空间\n  // 'docker' 已在册）。它和下面这些是同一类卡片，不该漏。\n  {\n    id: 'docker',\n    kind: 'card',\n    titles: ['Docker 容器面板', 'Docker Containers'],\n    keywords: ['docker', 'podman', '容器', 'container', '镜像', 'image', '网络', 'network', '卷', 'volume', 'compose', '日志'],\n    description: '容器 / 镜像 / 网络 / 卷的查看与变更，以及 SSH 远程 docker 目标',\n    registryName: 'docker',\n  },\n  {\n    id: 'loglens',\n    kind: 'card',\n    titles: ['日志查询', 'Log Query'],\n    keywords: ['loglens', '日志', 'log', 'loki', 'elasticsearch', 'opensearch', '检索', '查询'],\n    description: '把 Loki / Elasticsearch / OpenSearch / Docker 等日志来源归一化成一个查询面（面板侧只有来源清单与开关；查询走 agent 工具 loglens_*）',\n    registryName: 'loglens',\n  },\n]\n\nfunction getLoadedRegistryNames(ctx: Context): Set<string> {\n  const names = new Set<string>()\n  try {\n    const registry = (ctx as unknown as { registry?: { values?(): Iterable<{ name?: string }> } }).registry\n    if (registry?.values !== undefined) {\n      for (const runtime of registry.values()) {\n        if (typeof runtime.name === 'string' && runtime.name !== '') names.add(runtime.name)\n      }\n    }\n  } catch {\n    /* registry 枚举失败不阻塞 */\n  }\n  return names\n}\n\ninterface PanelHit {\n  id: string\n  /** section: 设置一级大类；card: 插件配置卡片 */\n  kind: 'section' | 'card'\n  name: string\n  /** 标题（中英），供客户端 openSettingsSection/openSettingsCard 匹配 */\n  titles: string[]\n  description: string\n  snippet: string\n}\n\n/** 目录条目：searchPanels 的输入，也是浏览器半体的「打开即有内容」目录。 */\ninterface PanelEntry extends Omit<PanelHit, 'snippet'> {\n  /** 额外可搜索关键词（与 PanelDefinition.keywords 同义） */\n  keywords: string[]\n}\n\n/**\n * 当前可用的设置面板清单：官方条目恒在，插件卡片按宿主已加载的插件过滤\n * （避免把未安装的卡片送给客户端）。\n * 浏览器半体的目录路由与 /query 的 panels 字段共用这一份清单。\n */\nfunction listPanels(ctx: Context): PanelEntry[] {\n  const loaded = getLoadedRegistryNames(ctx)\n  const items: PanelEntry[] = []\n  for (const panel of PANEL_DIRECTORY) {\n    if (panel.registryName !== undefined && !loaded.has(panel.registryName)) continue\n    items.push({\n      id: panel.id,\n      kind: panel.kind,\n      name: panel.titles[0],\n      titles: panel.titles,\n      keywords: panel.keywords,\n      description: panel.description,\n    })\n  }\n  return items\n}\n\nfunction searchPanels(ctx: Context, rawQuery: string, limit: number): PanelHit[] {\n  const query = normalizeQuery(rawQuery)\n  if (query === '') return []\n  const hits: PanelHit[] = []\n  for (const panel of listPanels(ctx)) {\n    if (hits.length >= limit) break\n    const searchable = [...panel.titles, ...panel.keywords, panel.description].map(normalizeQuery)\n    const matched = searchable.some((text) => text.includes(query))\n    if (!matched) continue\n    hits.push({\n      id: panel.id,\n      kind: panel.kind,\n      name: panel.name,\n      titles: panel.titles,\n      description: panel.description,\n      snippet: makeSnippet([...panel.titles, panel.description].join('，'), query),\n    })\n  }\n  return hits\n}\n\nfunction getService(ctx: Context, name: string): unknown {\n  const withGet = ctx as unknown as { get?: (service: string) => unknown }\n  if (typeof withGet.get === 'function') {\n    const value = withGet.get(name)\n    if (value !== undefined) return value\n  }\n  return (ctx as unknown as Record<string, unknown>)[name]\n}\n\n/* ------------------------------------------------------------------ *\n * HTTP 路由（loopback-only 围栏）\n * ------------------------------------------------------------------ */\n\ninterface ReqLike {\n  method?: string\n  url?: string\n  headers: Record<string, string | string[] | undefined>\n  socket: { remoteAddress?: string }\n}\n\ninterface ResLike {\n  writeHead(status: number, headers?: Record<string, string>): void\n  end(body?: string): void\n}\n\nfunction isLoopbackRequest(request: ReqLike): boolean {\n  const address = request.socket.remoteAddress\n  if (address !== '127.0.0.1' && address !== '::1' && address !== '::ffff:127.0.0.1') return false\n  const host = request.headers.host\n  if (typeof host !== 'string') return false\n  let hostUrl: URL\n  try {\n    hostUrl = new URL('http://' + host)\n  } catch {\n    return false\n  }\n  if (hostUrl.hostname !== '127.0.0.1' && hostUrl.hostname !== 'localhost' && hostUrl.hostname !== '[::1]') return false\n  if (request.headers['sec-fetch-site'] === 'cross-site') return false\n  const origin = request.headers.origin\n  if (origin === undefined) return true\n  try {\n    return new URL(origin).host === hostUrl.host\n  } catch {\n    return false\n  }\n}\n\nfunction writeJson(res: ResLike, status: number, body: unknown): void {\n  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'referrer-policy': 'no-referrer' })\n  res.end(JSON.stringify(body))\n}\n\ntype RouteHandler = (req: ReqLike, res: ResLike) => Promise<void>\n\nfunction makeRoutes(ctx: Context, config: Config): Array<{ kind: 'exact'; path: string; handler: RouteHandler }> {\n  const maxResults = Math.max(1, Math.min(50, config.maxResults ?? 8))\n  const maxScanSessions = Math.max(1, Math.min(500, config.maxScanSessions ?? MAX_SCAN_SESSIONS))\n  return [\n    {\n      kind: 'exact',\n      path: '/api/dsh-search/catalog',\n      handler: async (req, res) => {\n        if (!isLoopbackRequest(req)) {\n          writeJson(res, 403, { error: 'forbidden: loopback-only' })\n          return\n        }\n        if (req.method !== 'GET') {\n          writeJson(res, 405, { error: 'method not allowed: ' + String(req.method) })\n          return\n        }\n        // 目录是静态清单（不含用户数据），开关只受 includePanels 控制\n        writeJson(res, 200, { ok: true, panels: config.includePanels !== false ? listPanels(ctx) : [] })\n      },\n    },\n    {\n      kind: 'exact',\n      path: '/api/dsh-search/query',\n      handler: async (req, res) => {\n        if (!isLoopbackRequest(req)) {\n          writeJson(res, 403, { error: 'forbidden: loopback-only' })\n          return\n        }\n        if (req.method !== 'GET') {\n          writeJson(res, 405, { error: 'method not allowed: ' + String(req.method) })\n          return\n        }\n        let query = ''\n        try {\n          query = new URL('http://localhost' + (req.url ?? '/')).searchParams.get('q') ?? ''\n        } catch {\n          writeJson(res, 400, { error: 'invalid query string' })\n          return\n        }\n        const q = query.trim()\n        if (q === '') {\n          writeJson(res, 200, { ok: true, query: '', sessions: [], prompts: [], tools: [], panels: [] })\n          return\n        }\n        const controller = new AbortController()\n        const reqEvents = req as unknown as {\n          once(event: string, listener: () => void): void\n          removeListener(event: string, listener: () => void): void\n        }\n        const onClose = () => controller.abort()\n        reqEvents.once('close', onClose)\n        try {\n          const [sessions, prompts, tools, panels] = await Promise.all([\n            config.includeSessions !== false ? searchSessions(ctx, q, maxResults, controller.signal, maxScanSessions) : Promise.resolve([]),\n            config.includePrompts !== false ? Promise.resolve(searchPrompts(q, maxResults)) : Promise.resolve([]),\n            config.includeMcpTools !== false ? Promise.resolve(searchMcpTools(ctx, q, maxResults)) : Promise.resolve([]),\n            config.includePanels !== false ? Promise.resolve(searchPanels(ctx, q, maxResults)) : Promise.resolve([]),\n          ])\n          writeJson(res, 200, { ok: true, query: q, sessions, prompts, tools, panels })\n        } catch (error) {\n          writeJson(res, 500, { error: '搜索失败: ' + (error instanceof Error ? error.message : String(error)) })\n        } finally {\n          reqEvents.removeListener('close', onClose)\n        }\n      },\n    },\n  ]\n}\n\n/* ------------------------------------------------------------------ *\n * 插件本体\n * ------------------------------------------------------------------ */\n\nconst SEARCH_GUIDANCE = '本机已安装 dsh-search 插件（全局搜索）：Web GUI 侧边栏有「全局搜索」入口，⌘/Ctrl+K 也可唤出命令面板，可全文搜索历史会话、Prompt、MCP 工具与设置面板。'\n\nconst plugin = definePlugin<Config>({\n  name: 'global-search',\n  inject: [],\n  apply(ctx: Context, config?: Config) {\n    if (config?.enabled === false) return\n    const routes = makeRoutes(ctx, config ?? {})\n\n    ctx.inject(['webServer'], (webCtx: Context) => {\n      webCtx.effect(() => {\n        const server = (webCtx as unknown as { webServer: { register(route: { kind: string; path: string; handler: RouteHandler }): () => void } }).webServer\n        const disposers = routes.map((route) => server.register(route))\n        return () => {\n          for (const dispose of disposers) {\n            try {\n              dispose()\n            } catch {\n              /* 释放失败不阻塞 */\n            }\n          }\n        }\n      }, 'dsh-global-search: routes')\n    })\n\n    if (config?.announceToAgent !== false) {\n      ctx.inject(['systemPrompt'], (promptCtx: Context) => {\n        promptCtx.effect(() => {\n          const systemPrompt = (promptCtx as unknown as { systemPrompt: { section(options: { name: string; order?: number; text: string }): () => void } }).systemPrompt\n          return registerLiteralSection(systemPrompt, { name: 'plugin:dsh-global-search', order: 170, text: SEARCH_GUIDANCE })\n        }, 'dsh-global-search: announcement')\n      })\n    }\n\n    console.log('[dsh-global-search] mounted, prompt file: ' + promptFilePath())\n  },\n})\n\nexport const { name, inject, apply } = plugin\n"
    },
    {
      "path": "packages/search/client.js",
      "content": "/* eslint-disable */\n/**\n * @hyzyn/dsh-search — 浏览器半体：侧边栏「全局搜索」入口 + 命令面板式搜索窗。\n *\n * 面板结构（对齐主流命令面板 / 桌面端搜索窗的观感）：\n *   无边框输入行 → 分组行（最近会话 / 历史会话 / Prompt / MCP 工具 / 快捷操作 / 设置）\n *   → 底部按键提示条。行 = 图标 + 标题（可带副标题）+ 右侧元信息 + 快捷键胶囊。\n *\n * 打开即出内容：最近会话取自浏览器端 sessions 列表快照，快捷操作与设置目录即时渲染；\n * 输入后本地先过滤一遍（零延迟），宿主全文命中再由 /api/dsh-search/query 异步补齐。\n * 纯 DOM 渲染，无构建步骤；宿主经 /plugins/@hyzyn/dsh-search/client.js 提供。\n */\nwindow.__ModuleLoader__.load({\n  id: '@hyzyn/dsh-search',\n  factory: (require) => {\n    const exports = {}\n\n    /* ================================ CSS ================================ */\n\n    const CSS = [\n      // 侧边栏不在宿主 box-sizing reset 的作用域内：width:100% + 左右 padding 会按\n      // content-box 撑出 24px，右侧被侧边栏裁掉（hover 底色右边缺角）。必须显式声明。\n      // 侧边栏搜索框与行文本取宿主正文的角色（13 / 20）；行高按官方成对值写\n      // （规范：font-size 必须配 line-height，单行看不出、换行才不挤）。\n      '.gs_sidebarSearch{box-sizing:border-box;width:100%;height:32px;color:var(--dsw-alias-label-secondary);cursor:text;white-space:nowrap;background:0 0;border:1px solid transparent;border-radius:8px;align-items:center;gap:8px;padding:0 10px;font-size:13px;line-height:20px;display:flex}',\n      // 宿主 0.2.2-alpha.3 移除了旧版 sidebar-nav-item-hover 令牌；改用宿主侧栏\n      // 自己实际使用的 --dsw-alias-interactive-bg-hover——它在十二档 cohort 里都存在（证据见 README 兼容性段）。\n      '.gs_sidebarSearch:hover{background:var(--dsw-alias-interactive-bg-hover);color:var(--dsw-alias-label-primary)}',\n      '.gs_sidebarSearch:focus-within{border-color:var(--dsw-alias-state-business-primary);background:var(--dsw-specific-sidebar-nav-item-active);color:var(--dsw-alias-label-primary)}',\n      '.gs_sidebarSearchInput{flex:1;min-width:0;background:0 0;border:none;outline:none;color:inherit;font:inherit;padding:0}',\n      '.gs_sidebarSearchInput:focus,.gs_sidebarSearchInput:focus-visible{outline:none}',\n      '.gs_sidebarSearch:focus-within .gs_sidebarSearchInput{outline:none}',\n      '.gs_sidebarSearchInput::placeholder{color:var(--dsw-alias-label-tertiary)}',\n      '[data-sidebar-collapsed] .gs_sidebarSearch{justify-content:center;width:100%;padding:0;border-color:transparent}',\n      '[data-sidebar-collapsed] .gs_sidebarSearchInput{display:none}',\n\n      /* ---------- 面板骨架 ---------- */\n      '.gs_backdrop{z-index:1300;background:var(--dsw-alias-bg-mask-1);-webkit-backdrop-filter:blur(4px);backdrop-filter:blur(4px);justify-content:center;align-items:flex-start;display:flex;position:fixed;inset:0;padding:12vh 16px 24px}',\n      '.gs_palette{background:var(--dsw-alias-bg-base);border:0;border-radius:16px;width:min(640px,100%);max-height:min(600px,76vh);box-shadow:var(--dsw-elevation-prominent);color:var(--dsw-alias-label-primary);flex-direction:column;display:flex;overflow:hidden}',\n      '.gs_inputRow{flex:none;align-items:center;gap:10px;padding:14px 16px;border-bottom:.5px solid var(--dsw-alias-border-l1);color:var(--dsw-alias-label-tertiary);display:flex}',\n      '.gs_inputRow:focus-within{color:var(--dsw-alias-label-secondary)}',\n      '.gs_inputIcon{flex:none;justify-content:center;align-items:center;display:inline-flex}',\n      '.gs_input{flex:1;min-width:0;background:0 0;border:none;outline:none;color:var(--dsw-alias-label-primary);font:inherit;font-size:15px;line-height:22px;padding:0}',\n      '.gs_input:focus,.gs_input:focus-visible{outline:none}',\n      '.gs_input::placeholder{color:var(--dsw-alias-label-tertiary)}',\n      '.gs_list{flex:1;min-height:0;overflow-y:auto;padding:6px 8px 10px;scrollbar-width:thin}',\n      '.gs_list::-webkit-scrollbar{width:10px}',\n      '.gs_list::-webkit-scrollbar-track{background:transparent}',\n      '.gs_list::-webkit-scrollbar-thumb{background:var(--dsw-alias-scrollbar-bg-l2,var(--dsw-alias-border-l2));border:3px solid transparent;border-radius:999px;background-clip:content-box}',\n      '.gs_footer{flex:none;align-items:center;gap:14px;padding:8px 14px;border-top:.5px solid var(--dsw-alias-border-l1);color:var(--dsw-alias-label-tertiary);font-size:12px;line-height:18px;display:flex}',\n      '.gs_footerItem{align-items:center;display:inline-flex}',\n      '.gs_key{min-width:18px;height:18px;border:.5px solid var(--dsw-alias-border-l2);border-radius:var(--dsw-radius-sm);background:var(--dsw-alias-bg-layer-1);color:var(--dsw-alias-label-secondary);font-size:10px;line-height:1;justify-content:center;align-items:center;margin-right:5px;padding:0 4px;display:inline-flex}',\n\n      /* ---------- 分组与行 ---------- */\n      '.gs_group{flex-direction:column;gap:1px;display:flex;padding-top:8px}',\n      '.gs_group:first-child{padding-top:2px}',\n      // 分组标签是小号标签档（11px + 字距）：字号保留，只补官方成对行高 16，字重按区块标题取 500。\n      '.gs_groupLabel{color:var(--dsw-alias-label-tertiary);font-size:11px;font-weight:500;line-height:16px;letter-spacing:.04em;padding:0 10px 5px}',\n      // 统一行：图标 + 主列（标题/副标题）+ 右侧元信息 + 快捷键胶囊\n      '.gs_row{align-items:center;gap:10px;width:100%;min-height:38px;box-sizing:border-box;background:0 0;border:none;border-radius:var(--dsw-radius-sm);padding:6px 10px;color:var(--dsw-alias-label-primary);font:inherit;font-size:13px;line-height:20px;text-align:left;cursor:pointer;display:flex}',\n      '.gs_row:hover{background:var(--dsw-alias-interactive-bg-hover)}',\n      '.gs_row[data-active]{background:var(--dsw-alias-interactive-bg-active)}',\n      '.gs_rowIcon{flex:none;color:var(--dsw-alias-label-tertiary);justify-content:center;align-items:center;display:inline-flex}',\n      '.gs_row[data-active] .gs_rowIcon{color:var(--dsw-alias-label-secondary)}',\n      '.gs_rowMain{flex:1;min-width:0;flex-direction:column;gap:1px;display:flex}',\n      // 标题/副标题都是普通行内流：写成 flex 会把「文本 + <mark> + 文本」拆成匿名 flex 项，\n      // 高亮词组被拦腰折断\n      '.gs_rowTitle{font-weight:500;line-height:1.45;display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}',\n      '.gs_rowSub{color:var(--dsw-alias-label-tertiary);font-size:12px;line-height:18px;display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}',\n      '.gs_rowMeta{flex:none;color:var(--dsw-alias-label-tertiary);font-size:12px;line-height:18px;white-space:nowrap}',\n      '.gs_rowChip{flex:none;min-width:22px;height:20px;border-radius:var(--dsw-radius-sm);background:var(--dsw-alias-bg-layer-2);color:var(--dsw-alias-label-tertiary);font-size:11px;font-weight:600;line-height:16px;justify-content:center;align-items:center;padding:0 5px;display:inline-flex}',\n      '.gs_rowGhost{color:var(--dsw-alias-label-tertiary);cursor:default}',\n      '.gs_rowGhost:hover{background:0 0}',\n      '.gs_badge{display:inline-block;border:.5px solid var(--dsw-alias-border-l2);color:var(--dsw-alias-label-secondary);border-radius:999px;corner-shape:round;padding:0 7px;font-size:10px;line-height:14px;white-space:nowrap;margin-left:8px;vertical-align:middle}',\n      // 高亮词是「一个整体」，不能被行尾折断（CJK 会逐字断行 → 词组被劈成两行）\n      '.gs_highlight{background:var(--dsw-alias-state-warn-tertiary);color:inherit;border-radius:var(--dsw-radius-xs);padding:0 1px;white-space:nowrap}',\n      '.gs_hint{text-align:center;color:var(--dsw-alias-label-tertiary);padding:26px 12px;font-size:12.5px;line-height:18px}',\n      '.gs_error{text-align:center;color:var(--dsw-alias-state-error-primary);padding:22px 12px;font-size:12.5px;line-height:18px}',\n      '.gs_spinner{width:12px;height:12px;border:1.6px solid var(--dsw-alias-border-l3);border-top-color:var(--dsw-alias-label-tertiary);border-radius:50%;corner-shape:round;animation:gs_spin .8s linear infinite;display:inline-block}',\n      '@keyframes gs_spin{to{transform:rotate(360deg)}}',\n\n      /* ---------- toast ---------- */\n      '.gs_toast{position:fixed;left:50%;bottom:36px;transform:translateX(-50%);z-index:2147483647;pointer-events:none;background:var(--dsw-alias-bg-layer-2);border:0;color:var(--dsw-alias-label-primary);border-radius:var(--dsw-radius-md);padding:9px 16px;font-size:13px;line-height:20px;box-shadow:var(--dsw-elevation-prominent);max-width:70vw}',\n      '.gs_toast[data-kind=ok]{color:var(--dsw-alias-state-success-primary);box-shadow:var(--dsw-elevation-prominent), inset 0 0 0 .5px var(--dsw-alias-state-success-primary)}',\n      '.gs_toast[data-kind=error]{color:var(--dsw-alias-state-error-primary);box-shadow:var(--dsw-elevation-prominent), inset 0 0 0 .5px var(--dsw-alias-state-error-primary)}',\n    ].join('\\n')\n\n    let styleEl\n    function ensureStyle() {\n      if (document.getElementById('dsh-search-style')) return\n      styleEl = document.createElement('style')\n      styleEl.id = 'dsh-search-style'\n      styleEl.textContent = CSS\n      document.head.appendChild(styleEl)\n    }\n\n    /* ================================ 国际化 ================================ */\n\n    /*\n     * 界面文案走宿主 `@deepseek-ai/dsh-client-locale` 的目录（方案见 docs/i18n.md）。\n     * 下面这一对目录由 `scripts/check-i18n.mjs` 静态校验：键集必须与英文一一对应、\n     * `{name}` 占位符两边一致、代码里 `t('…')` 用到的键必须在这里有定义。\n     * 目录**内联在 client.js 里**（不是 client-src/）：本包没有构建步骤，client.js 就是源；\n     * 而且一旦凭空建出 client-src/，仓库级「宿主地址来源」静态规则会停止覆盖 client.js。\n     */\n    /* ==== dsh-i18n:begin ==== */\n    const I18N_NS = 'search'\n    const I18N_ZH = {\n      'card.name': '全局搜索',\n      'card.prompt': 'Prompt 管理',\n      'card.mcp': 'MCP 服务器配置',\n      'panel.results': '搜索结果',\n      'panel.hintSelect': '选择',\n      'panel.hintOpen': '打开',\n      'panel.hintClose': '关闭',\n      'panel.recent': '最近',\n      'panel.recentSessions': '最近会话',\n      'panel.historySessions': '历史会话',\n      'panel.mcpTools': 'MCP 工具',\n      'panel.actions': '快捷操作',\n      'panel.settings': '设置',\n      'panel.untitled': '设置面板',\n      'panel.general': '通用设置',\n      'panel.generalDesc': '界面与工具的通用选项',\n      'panel.models': '模型',\n      'panel.modelsDesc': '模型提供商与模型列表管理',\n      'panel.plugins': '内置插件',\n      'panel.pluginsDesc': '插件清单与插件管理',\n      'panel.agentPresets': 'Agent 预设',\n      'panel.agentPresetsDesc': '预设方案与角色模板',\n      'btn.newSession': '新会话',\n      'btn.openFolder': '打开文件夹',\n      'btn.openSettings': '打开设置',\n      'list.justNow': '刚刚',\n      'list.minutesAgo': '{count} 分钟前',\n      'list.hoursAgo': '{count} 小时前',\n      'list.daysAgo': '{count} 天前',\n      'list.active': '启用中',\n      'list.searching': '搜索会话全文…',\n      'list.hintEmpty': '输入关键词，搜索历史会话、Prompt、MCP 工具和设置面板。',\n      'list.hintKeys': '↑↓ 选择，↵ 打开，esc 关闭。',\n      'list.empty': '没有找到匹配结果。',\n      'msg.copied': '已复制',\n      'msg.openedCard': '已打开「{name}」设置卡片',\n      'msg.openedSection': '已打开「{name}」设置分区',\n      'error.newSession': '新建会话失败',\n      'error.openSession': '打开会话失败',\n      'error.newSessionUnavailable': '当前环境无法新建会话',\n      'error.openSessionUnavailable': '当前环境无法直接打开会话',\n      'error.openFolderUnavailable': '当前环境无法打开文件夹',\n      'error.openSettingsUnavailable': '当前环境无法打开设置',\n      'error.copyFailed': '复制失败',\n      'placeholder.sidebar': '全局搜索…',\n      'placeholder.panel': '搜索会话、设置与工具…',\n    }\n    const I18N_EN = {\n      'card.name': 'Global search',\n      'card.prompt': 'Prompt management',\n      'card.mcp': 'MCP server configuration',\n      'panel.results': 'Search results',\n      'panel.hintSelect': 'Select',\n      'panel.hintOpen': 'Open',\n      'panel.hintClose': 'Close',\n      'panel.recent': 'Recent',\n      'panel.recentSessions': 'Recent sessions',\n      'panel.historySessions': 'Session matches',\n      'panel.mcpTools': 'MCP tools',\n      'panel.actions': 'Quick actions',\n      'panel.settings': 'Settings',\n      'panel.untitled': 'Settings panel',\n      'panel.general': 'General',\n      'panel.generalDesc': 'General options for the interface and tools',\n      'panel.models': 'Models',\n      'panel.modelsDesc': 'Manage model providers and the model list',\n      'panel.plugins': 'Built-in plugins',\n      'panel.pluginsDesc': 'Plugin list and plugin management',\n      'panel.agentPresets': 'Agent presets',\n      'panel.agentPresetsDesc': 'Presets and role templates',\n      'btn.newSession': 'New session',\n      'btn.openFolder': 'Open folder',\n      'btn.openSettings': 'Open settings',\n      'list.justNow': 'Just now',\n      'list.minutesAgo': '{count} minutes ago',\n      'list.hoursAgo': '{count} hours ago',\n      'list.daysAgo': '{count} days ago',\n      'list.active': 'Active',\n      'list.searching': 'Searching session contents…',\n      'list.hintEmpty': 'Type to search past sessions, prompts, MCP tools and settings panels.',\n      'list.hintKeys': '↑↓ to select, ↵ to open, esc to close.',\n      'list.empty': 'No matching results.',\n      'msg.copied': 'Copied',\n      'msg.openedCard': 'Opened the “{name}” settings card',\n      'msg.openedSection': 'Opened the “{name}” settings section',\n      'error.newSession': 'Failed to create a session',\n      'error.openSession': 'Failed to open the session',\n      'error.newSessionUnavailable': 'This environment cannot create sessions',\n      'error.openSessionUnavailable': 'This environment cannot open sessions directly',\n      'error.openFolderUnavailable': 'This environment cannot open folders',\n      'error.openSettingsUnavailable': 'This environment cannot open settings',\n      'error.copyFailed': 'Copy failed',\n      'placeholder.sidebar': 'Search…',\n      'placeholder.panel': 'Search sessions, settings and tools…',\n    }\n    /* ==== dsh-i18n:end ==== */\n\n    /** 占位符替换：`{name}` → params.name（缺参留空，不抛错——文案不该打死界面）。 */\n    function i18nFormat(text, params) {\n      if (params === undefined) return text\n      return String(text).replace(/\\{(\\w+)\\}/g, (_match, name) => (params[name] === undefined ? '' : String(params[name])))\n    }\n\n    /** 中文兜底：老宿主（DSH ≤0.1.5）没有 locale 服务时，界面不能变成一串键名。 */\n    function i18nFallback(key, params) {\n      return i18nFormat(I18N_ZH[key] !== undefined ? I18N_ZH[key] : key, params)\n    }\n\n    let t = i18nFallback\n\n    /**\n     * Sidebar entries created so far. An entry bakes its visible text into\n     * `innerHTML` at creation, so a locale switch cannot re-render it the way a\n     * slot outlet re-renders: without this set the placeholder and aria-label\n     * stay in the language that was active when the page loaded.\n     */\n    const sidebarEntries = new Set()\n\n    function refreshEntryLabels(entry) {\n      if (entry === undefined || entry === null) return\n      entry.setAttribute('aria-label', t('card.name'))\n      const input = entry.querySelector('.gs_sidebarSearchInput')\n      if (input !== null) input.setAttribute('placeholder', t('placeholder.sidebar'))\n    }\n\n    function refreshAllEntryLabels() {\n      for (const entry of sidebarEntries) refreshEntryLabels(entry)\n    }\n\n    /**\n     * 注册目录并绑定翻译函数。**动态 inject**：老宿主上回调永不触发、`t` 保持中文兜底；\n     * 写成静态 `inject: ['locale']` 会让整张卡片在老宿主上根本不挂。\n     *\n     * 语言切换不用自己订阅：插槽 outlet 随 locale revision 重渲染（renderer 的\n     * `useLocaleRevision`），而 `bind()` 返回的翻译函数在**调用时**读当前语言。\n     */\n    function installI18n(ctx) {\n      ctx.inject(['locale'], (i18nCtx) => {\n        const disposeZh = i18nCtx.locale.register(I18N_NS, 'zh', I18N_ZH)\n        const disposeEn = i18nCtx.locale.register(I18N_NS, 'en', I18N_EN)\n        t = i18nCtx.locale.bind(I18N_NS)\n        // Entries that already exist were created before this binding; repaint\n        // them now and again on every later locale switch.\n        refreshAllEntryLabels()\n        const disposeSub = typeof i18nCtx.locale.subscribe === 'function'\n          ? i18nCtx.locale.subscribe(refreshAllEntryLabels)\n          : undefined\n        return () => {\n          if (disposeSub !== undefined) disposeSub()\n          disposeEn()\n          disposeZh()\n          t = i18nFallback\n        }\n      })\n    }\n\n    /* ================================ 基础工具 ================================ */\n\n    const ESC_MAP = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }\n    const esc = (value) => String(value == null ? '' : value).replace(/[&<>\"']/g, (c) => ESC_MAP[c])\n\n    const IS_MAC = /mac|iphone|ipad|ipod/i.test((navigator.platform || '') + ' ' + (navigator.userAgent || ''))\n    /** 快捷键胶囊前缀：macOS 用 ⌥，其余平台用 Alt+ */\n    const ALT_LABEL = IS_MAC ? '⌥' : 'Alt+'\n\n    function relativeTime(value) {\n      if (!value) return ''\n      const date = new Date(value)\n      if (Number.isNaN(date.getTime())) return ''\n      const diff = Date.now() - date.getTime()\n      if (diff < 60 * 1000) return t('list.justNow')\n      const minutes = Math.floor(diff / (60 * 1000))\n      if (minutes < 60) return t('list.minutesAgo', { count: minutes })\n      const hours = Math.floor(minutes / 60)\n      if (hours < 24) return t('list.hoursAgo', { count: hours })\n      const days = Math.floor(hours / 24)\n      if (days < 30) return t('list.daysAgo', { count: days })\n      return date.toLocaleDateString()\n    }\n\n    /**\n     * 按空白拆词后逐词高亮（与服务端把空格编译成 \\s+ 的弹性匹配对齐）。\n     * 词组为空时原样转义返回；单词时与旧的整串匹配等价。\n     */\n    function highlightText(text, query) {\n      const value = String(text == null ? '' : text)\n      const words = String(query == null ? '' : query)\n        .trim()\n        .split(/\\s+/)\n        .filter((word) => word !== '')\n      if (words.length === 0) return esc(value)\n      // 正则元字符转义后用 | 连接，一次全局扫描逐段拼接\n      const pattern = words.map((word) => word.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&')).join('|')\n      let regex\n      try {\n        regex = new RegExp(pattern, 'giu')\n      } catch {\n        return esc(value)\n      }\n      const parts = []\n      let lastIndex = 0\n      let match = regex.exec(value)\n      while (match !== null) {\n        if (match[0] === '') {\n          // 空匹配兜底：只推进扫描位置，避免死循环\n          regex.lastIndex = match.index + 1\n          match = regex.exec(value)\n          continue\n        }\n        parts.push(esc(value.slice(lastIndex, match.index)))\n        parts.push('<mark class=\"gs_highlight\">' + esc(match[0]) + '</mark>')\n        lastIndex = match.index + match[0].length\n        regex.lastIndex = lastIndex\n        match = regex.exec(value)\n      }\n      parts.push(esc(value.slice(lastIndex)))\n      return parts.join('')\n    }\n\n    async function api(path, signal) {\n      const res = await fetch(path, { cache: 'no-store', signal })\n      let body = {}\n      try {\n        body = await res.json()\n      } catch {\n        /* 非 JSON 响应 */\n      }\n      if (!res.ok) {\n        throw new Error((body && body.error) || ('HTTP ' + res.status))\n      }\n      return body\n    }\n\n    /* ================================ 图标（24 栅格线性图标，随字号取 16px） ================================ */\n\n    const SVG_OPEN = '<svg viewBox=\"0 0 24 24\" width=\"16\" height=\"16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">'\n    const icon = (paths) => SVG_OPEN + paths + '</svg>'\n\n    const ICONS = {\n      search: icon('<circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m20 20-3.6-3.6\"/>'),\n      chat: icon('<path d=\"M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8z\"/>'),\n      file: icon('<path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><path d=\"M14 2v6h6\"/><path d=\"M16 13H8M16 17H8M10 9H8\"/>'),\n      plug: icon('<path d=\"M12 22v-4\"/><path d=\"M9 8V2M15 8V2\"/><path d=\"M18 8v5a4 4 0 0 1-4 4h-4a4 4 0 0 1-4-4V8z\"/>'),\n      sliders: icon('<path d=\"M21 4h-7M10 4H3M21 12h-9M8 12H3M21 20h-5M12 20H3\"/><path d=\"M14 2v4M8 10v4M16 18v4\"/>'),\n      gear: icon('<path d=\"M12.2 2h-.4a2 2 0 0 0-2 2v.2a2 2 0 0 1-1 1.7l-.4.3a2 2 0 0 1-2 0l-.2-.1a2 2 0 0 0-2.7.7l-.2.4a2 2 0 0 0 .7 2.7l.2.1a2 2 0 0 1 1 1.7v.5a2 2 0 0 1-1 1.7l-.2.1a2 2 0 0 0-.7 2.7l.2.4a2 2 0 0 0 2.7.7l.2-.1a2 2 0 0 1 2 0l.4.3a2 2 0 0 1 1 1.7V20a2 2 0 0 0 2 2h.4a2 2 0 0 0 2-2v-.2a2 2 0 0 1 1-1.7l.4-.3a2 2 0 0 1 2 0l.2.1a2 2 0 0 0 2.7-.7l.2-.4a2 2 0 0 0-.7-2.7l-.2-.1a2 2 0 0 1-1-1.7v-.5a2 2 0 0 1 1-1.7l.2-.1a2 2 0 0 0 .7-2.7l-.2-.4a2 2 0 0 0-2.7-.7l-.2.1a2 2 0 0 1-2 0l-.4-.3a2 2 0 0 1-1-1.7V4a2 2 0 0 0-2-2z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/>'),\n      newChat: icon('<path d=\"M12 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7\"/><path d=\"M18.4 2.6a2 2 0 0 0 2.9 2.9L12 14.8l-4 1 1-4z\"/>'),\n      folder: icon('<path d=\"M4 20h16a2 2 0 0 0 2-2V8a2 2 0 0 0-2-2h-7.9a2 2 0 0 1-1.7-.9l-.8-1.2A2 2 0 0 0 7.9 3H4a2 2 0 0 0-2 2v13a2 2 0 0 0 2 2z\"/>'),\n    }\n\n    /*\n     * 侧边栏入口图标单独一份，**不共用** ICONS：ICONS 是 24 栅格按 16px 渲染，线宽折合\n     * 1.8×16/24 ≈ 1.2px、图形也只有 10.7px 高；而它左右邻居（rss / tty / docker 的入口）\n     * 统一是「16 栅格 + 18×18 + stroke 1.7」，折合线宽 ≈ 1.9px、图形 ≈ 12px。并排放在\n     * 侧边栏里，共用那套的放大镜明显偏细偏小。这里把同一形状换算到 16 栅格（中心 7.3、\n     * 半径 4.7、手柄到 13.3），套用邻居的尺寸与线宽。面板内部仍用 ICONS 那套。\n     */\n    const ENTRY_ICON = '<svg viewBox=\"0 0 16 16\" width=\"18\" height=\"18\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"7.3\" cy=\"7.3\" r=\"4.7\"/><path d=\"m13.3 13.3-2.4-2.4\"/></svg>'\n\n    /* ================================ 状态 ================================ */\n\n    const state = {\n      query: '',\n      loading: false,\n      error: '',\n      /** 宿主 /query 的三类异步命中 */\n      server: { sessions: [], prompts: [], tools: [], panels: [] },\n      /** 设置目录（打开即用；加载失败时退回服务端 panels） */\n      catalog: { ready: false, panels: [] },\n    }\n\n    let paletteEl = null\n    let listEl = null\n    let inputEl = null\n    let toastEl = null\n    let toastTimer = null\n    let searchTimer = null\n    let searchSeq = 0\n    let activeCtx = null\n    let activeCtl = null\n    let activeItemIndex = -1\n    let currentEntries = []\n    let lastFocused = null\n    let globalKeyHandler = null\n    let sessionUnsubscribe = null\n    let sessionRenderTimer = null\n\n    function toast(message, kind) {\n      if (toastEl === null || !toastEl.isConnected) {\n        toastEl = document.createElement('div')\n        toastEl.className = 'gs_toast'\n        document.body.appendChild(toastEl)\n      }\n      toastEl.textContent = message\n      toastEl.dataset.kind = kind || 'info'\n      toastEl.style.display = ''\n      clearTimeout(toastTimer)\n      toastTimer = setTimeout(() => {\n        toastEl.style.display = 'none'\n      }, 2600)\n    }\n\n    /* ================================ 侧边栏入口 ================================ */\n\n    function sidebarRoot() {\n      const column = document.querySelector('[data-pane=\"sidebar\"], [class*=\"sidebarCol\"]')\n      if (column === null) return undefined\n      return column.querySelector('[class*=\"logoRow\"]')?.parentElement ?? column.firstElementChild\n    }\n\n    function newSessionButton(root) {\n      const nested = root.querySelector('button[class*=\"newSession\"]')\n      if (nested !== null) return nested\n      for (const child of root.children) {\n        if (child.tagName === 'BUTTON') return child\n      }\n      return undefined\n    }\n\n    /**\n     * 关闭后的极短窗口内忽略入口的 focusin：焦点在入口内部来回移动时\n     * （入口 focusin 就是打开路径）不至于把关掉的面板又弹回来。\n     */\n    let entryFocusMutedUntil = 0\n\n    /** 元素是否在侧边栏搜索入口内部（含入口自身）。 */\n    function insideSearchEntry(element) {\n      if (!element) return false\n      const entry = document.querySelector('[data-dsh-global-search-entry]')\n      if (entry === null) return false\n      return entry === element || (typeof entry.contains === 'function' && entry.contains(element))\n    }\n\n    function createSidebarEntry() {\n      const entry = document.createElement('div')\n      entry.dataset.dshGlobalSearchEntry = ''\n      entry.className = 'gs_sidebarSearch'\n      entry.setAttribute('role', 'search')\n      entry.setAttribute('aria-label', t('card.name'))\n      entry.innerHTML = '<span class=\"gs_sidebarEntryIcon\">' + ENTRY_ICON + '</span><input class=\"gs_sidebarSearchInput\" placeholder=\"' + esc(t('placeholder.sidebar')) + '\" readOnly />'\n      sidebarEntries.add(entry)\n      refreshEntryLabels(entry)\n      entry.addEventListener('click', (event) => {\n        event.preventDefault()\n        openPalette()\n      })\n      entry.addEventListener('focusin', () => {\n        if (Date.now() < entryFocusMutedUntil) return\n        openPalette()\n      })\n      return entry\n    }\n\n    function placeSidebarEntry(root, entry) {\n      const button = newSessionButton(root)\n      if (button === undefined) return false\n      if (entry.parentElement !== root) {\n        const row = button.closest('[class*=\"logoRow\"]')\n        const base = row !== null && row.parentElement === root ? row : button\n        const family = Array.from(root.children).filter((el) => el instanceof HTMLElement && el.matches('[data-dsh-global-search-entry], [data-dsh-rss-entry], [data-dsh-taskboard-entry], [data-dsh-ssh-entry]'))\n        if (family.length > 0) {\n          const last = family[family.length - 1]\n          root.insertBefore(entry, last.nextSibling)\n        } else {\n          root.insertBefore(entry, base.nextElementSibling)\n        }\n      }\n      return true\n    }\n\n    function mountSidebarEntry() {\n      if (typeof document !== 'undefined' && document.querySelector('[data-dsh-global-search-entry]') !== null) return () => {}\n      const entry = createSidebarEntry()\n      let root\n      let placed = false\n\n      const tryPlace = () => {\n        if (root !== undefined && !root.isConnected) {\n          rootObserver.disconnect()\n          root = undefined\n          placed = false\n        }\n        if (placed) {\n          if (document.body.contains(entry)) return\n          rootObserver.disconnect()\n          root = undefined\n          placed = false\n        }\n        root ??= sidebarRoot()\n        if (root === undefined) return\n        placed = placeSidebarEntry(root, entry)\n        if (placed) {\n          rootObserver.observe(root, { childList: true, subtree: true })\n        }\n      }\n\n      const waitObserver = new MutationObserver(() => {\n        tryPlace()\n      })\n      waitObserver.observe(document.body, { childList: true, subtree: true })\n\n      const rootObserver = new MutationObserver(() => {\n        if (root === undefined || !root.isConnected) {\n          placed = false\n          tryPlace()\n          return\n        }\n        if (!root.contains(entry)) placed = placeSidebarEntry(root, entry)\n      })\n\n      tryPlace()\n      return () => {\n        waitObserver.disconnect()\n        rootObserver.disconnect()\n        entry.remove()\n      }\n    }\n\n    /* ================================ 本地数据源 ================================ */\n\n    /**\n     * 浏览器端会话列表快照（ctx.sessions.list）。\n     * 形状不稳定时不抛错，只是「没有最近会话」——面板其余部分照常可用。\n     */\n    function readSessionSummaries() {\n      const sessions = activeCtx && activeCtx.sessions\n      const store = sessions && sessions.list\n      if (!store) return []\n      let snapshot\n      try {\n        snapshot = typeof store.getSnapshot === 'function'\n          ? store.getSnapshot()\n          : (typeof store.get === 'function' ? store.get() : undefined)\n      } catch {\n        return []\n      }\n      if (!snapshot || typeof snapshot.byId !== 'object' || snapshot.byId === null || !Array.isArray(snapshot.ids)) return []\n      const rows = []\n      for (const id of snapshot.ids) {\n        const row = snapshot.byId[id]\n        if (!row) continue\n        if (row.origin === 'subagent') continue\n        // 空会话（新建后没说过话）不算「最近会话」\n        if (row.blank) continue\n        rows.push({\n          id,\n          title: row.displayTitle || row.title || id,\n          time: typeof row.updatedAt === 'number' ? row.updatedAt : 0,\n        })\n      }\n      rows.sort((a, b) => b.time - a.time)\n      return rows\n    }\n\n    /** 侧边栏「添加工作区」按钮：目录选择器插件缺席时按钮不存在，动作随之隐藏。 */\n    function findWorkspaceAddButton() {\n      const scope = document.querySelector('[data-pane=\"sidebar\"], [class*=\"sidebarCol\"]') || document\n      const buttons = scope.querySelectorAll('button[aria-label]')\n      for (const button of buttons) {\n        const label = button.getAttribute('aria-label') || ''\n        if (/工作区|workspace/i.test(label)) return button\n      }\n      return null\n    }\n\n    /**\n     * GUI 自己的「新会话 / 打开会话」服务（dsh-client-ui-workspace 注册的 cordis Service）。\n     * 它才会复用当前工作区的空会话、创建后选中并在主区切过去；只调 sessions.create()\n     * 是「建了但不选」，用户看到的就是点击没反应。\n     *\n     * 0.1.6 起「打开会话」也归它（`openSession`）——会话域的 `sessions.open()` 已移除。\n     */\n    function uiWorkspaceService() {\n      try {\n        const ctx = activeCtx\n        if (!ctx) return undefined\n        let service = typeof ctx.get === 'function' ? ctx.get('uiWorkspace') : undefined\n        if (service === undefined) service = ctx.uiWorkspace\n        if (service === undefined || service === null) return undefined\n        // 两个能力任一可用即可（老版本 uiWorkspace 可能只有 startSession）\n        return typeof service.startSession === 'function' || typeof service.openSession === 'function' ? service : undefined\n      } catch {\n        return undefined\n      }\n    }\n\n    function canCreateSession() {\n      if (uiWorkspaceService() !== undefined) return true\n      const sessions = activeCtx && activeCtx.sessions\n      if (sessions && typeof sessions.create === 'function') return true\n      const root = sidebarRoot()\n      return root !== undefined && newSessionButton(root) !== undefined\n    }\n\n    /** 新会话：优先走 GUI 服务，其次点侧边栏按钮，最后才自己建并选中。 */\n    async function runNewSession() {\n      const uiWorkspace = uiWorkspaceService()\n      if (uiWorkspace !== undefined) {\n        try {\n          await uiWorkspace.startSession()\n          return\n        } catch (error) {\n          console.warn('[dsh-global-search] uiWorkspace.startSession failed:', error)\n        }\n      }\n      const root = sidebarRoot()\n      const button = root === undefined ? undefined : newSessionButton(root)\n      if (button !== undefined) {\n        button.click()\n        return\n      }\n      const sessions = activeCtx && activeCtx.sessions\n      if (sessions && typeof sessions.create === 'function') {\n        try {\n          const id = await sessions.create()\n          // create 只建不选：必须再 open，否则界面停在原会话上\n          if (id !== undefined && id !== null && typeof sessions.open === 'function') sessions.open(id)\n          return\n        } catch (error) {\n          toast(error && error.message ? error.message : t('error.newSession'), 'error')\n          return\n        }\n      }\n      toast(t('error.newSessionUnavailable'), 'error')\n    }\n\n    function runOpenFolder() {\n      const button = findWorkspaceAddButton()\n      if (button === null) {\n        toast(t('error.openFolderUnavailable'), 'error')\n        return\n      }\n      button.click()\n    }\n\n    async function runOpenSettings() {\n      if (!settingsEntryAvailable()) {\n        toast(t('error.openSettingsUnavailable'), 'error')\n        return\n      }\n      if (await openSettingsDialog() === null) toast(t('error.openSettingsUnavailable'), 'error')\n    }\n\n    /** 快捷操作：可用性在渲染时判定，不可用的行不出现（宁缺毋滥）。 */\n    const QUICK_ACTIONS = [\n      {\n        id: 'new-session',\n        get title() { return t('btn.newSession') },\n        icon: 'newChat',\n        code: 'KeyN',\n        chip: 'N',\n        keywords: ['new', 'chat', 'session', '新建', '新会话', '聊天', '对话'],\n        available: () => canCreateSession(),\n        run: () => runNewSession(),\n      },\n      {\n        id: 'open-folder',\n        get title() { return t('btn.openFolder') },\n        icon: 'folder',\n        code: 'KeyO',\n        chip: 'O',\n        keywords: ['folder', 'workspace', 'open', '文件夹', '目录', '工作区', '打开'],\n        available: () => findWorkspaceAddButton() !== null,\n        run: () => runOpenFolder(),\n      },\n      {\n        id: 'open-settings',\n        get title() { return t('btn.openSettings') },\n        icon: 'sliders',\n        code: 'Comma',\n        chip: ',',\n        keywords: ['settings', 'preference', 'config', '设置', '偏好', '配置'],\n        available: () => settingsEntryAvailable(),\n        run: () => runOpenSettings(),\n      },\n    ]\n\n    let catalogAttemptAt = 0\n\n    /**\n     * 设置目录：进面板时拉一次，成功后常驻内存。\n     * 失败不锁死——宿主还是旧版本（没有 /catalog 路由）时，下次打开面板再试一次；\n     * 期间退回服务端 /query 的 panels（旧行为），面板其余部分照常可用。\n     */\n    async function loadCatalog() {\n      if (state.catalog.ready) return\n      const now = Date.now()\n      if (now - catalogAttemptAt < 3000) return\n      catalogAttemptAt = now\n      try {\n        const data = await api('/api/dsh-search/catalog')\n        state.catalog = { ready: true, panels: Array.isArray(data.panels) ? data.panels : [] }\n      } catch {\n        return\n      }\n      if (paletteEl !== null) render()\n    }\n\n    /* ================================ 条目构建 ================================ */\n\n    function toolServerName(name) {\n      const parts = String(name == null ? '' : name).split('__')\n      return parts.length >= 3 ? parts[1] : ''\n    }\n\n/**\n     * showSubtitle=false 用于空查询下的一级大类（对齐参考图的单行设置行）。\n     * sectionIndex = 该大类在注册表里的序号，与设置窗导航按钮顺序一致（文本匹配失败时的兜底）。\n     */\n    function entryFromPanel(panel, showSubtitle, sectionIndex) {\n      const titles = Array.isArray(panel.titles) && panel.titles.length > 0 ? panel.titles : [panel.name]\n      return {\n        kind: 'panel',\n        icon: panel.kind === 'section' ? 'sliders' : 'gear',\n        title: highlightText(panel.name, state.query),\n        subtitle: showSubtitle && panel.description ? highlightText(panel.description, state.query) : '',\n        payload: {\n          titles,\n          section: panel.kind === 'section',\n          name: panel.name,\n          index: typeof sectionIndex === 'number' ? sectionIndex : -1,\n        },\n      }\n    }\n\n    /**\n     * 官方设置大类的兜底清单：只在宿主没提供 /api/dsh-search/catalog 时用\n     * （宿主本体是旧版本、路由尚未注册，或目录请求失败）。五个大类都是 DSH 内置的，\n     * 有它「设置」分组才不会空着；插件卡片仍由 /query 的 panels 补齐。\n     *\n     * `name` / `description` 是**要显示**的文案，必须走 t()，所以这里现取现建（不能做成\n     * 模块级常量——那时 `t` 还没绑定，语言一切换就露中文）；`titles` / `keywords` 是拿去匹配\n     * 宿主已渲染 DOM 的**宿主标签**，与语言无关，zh/en 都留着。\n     */\n    const fallbackSections = () => [\n      { id: 's-general', kind: 'section', name: t('panel.general'), titles: ['通用设置', 'General'], keywords: ['general', '通用', '设置', '常规', '基础'], description: t('panel.generalDesc') },\n      { id: 's-models', kind: 'section', name: t('panel.models'), titles: ['模型', 'Models'], keywords: ['model', 'models', '模型', '提供商', 'provider', '推理'], description: t('panel.modelsDesc') },\n      { id: 's-plugins', kind: 'section', name: t('panel.plugins'), titles: ['内置插件', 'Built-in plugins'], keywords: ['plugin', 'plugins', '插件', '内置插件', '扩展'], description: t('panel.pluginsDesc') },\n      { id: 's-agent-presets', kind: 'section', name: t('panel.agentPresets'), titles: ['Agent 预设', 'Agent presets'], keywords: ['agent', 'preset', '预设', 'agent preset', 'agentpresets'], description: t('panel.agentPresetsDesc') },\n    ]\n\n    /* ---------- 设置目录：实时 slots 注册表 + 宿主目录 + 兜底清单 ---------- */\n\n    /** 客户端 slots 服务（SlotRegistry）：设置大类是它的 settings.section 列表槽。 */\n    function slotsService() {\n      try {\n        const ctx = activeCtx\n        if (!ctx) return undefined\n        let service = typeof ctx.get === 'function' ? ctx.get('slots') : undefined\n        if (service === undefined) service = ctx.slots\n        return service !== undefined && service !== null && typeof service.entries === 'function' ? service : undefined\n      } catch {\n        return undefined\n      }\n    }\n\n    /** slot 的 label 可能是字符串，也可能是 thunk（注册方随语言环境重新注册）。 */\n    function slotLabel(value) {\n      if (typeof value === 'string') return value\n      if (typeof value === 'function') {\n        try {\n          const out = value()\n          return typeof out === 'string' ? out : ''\n        } catch {\n          return ''\n        }\n      }\n      return ''\n    }\n\n    /**\n     * 实时枚举设置一级大类（settings.section 槽）。\n     * 这是拿到第三方大类的唯一来源——皮肤 / 宠物 / 侧边卡片 / Web 插件 这些\n     * 插件注册的大类在宿主静态目录里根本不存在。顺序与设置窗导航一致（按 order 排序），\n     * 因此第 N 条对应导航第 N 个按钮。\n     */\n    function liveSections() {\n      const slots = slotsService()\n      if (slots === undefined) return []\n      let entries\n      try {\n        entries = slots.entries('settings.section')\n      } catch {\n        return []\n      }\n      if (!Array.isArray(entries)) return []\n      const rows = []\n      for (const entry of entries) {\n        const options = entry && typeof entry.options === 'object' && entry.options !== null ? entry.options : {}\n        const label = slotLabel(options.label)\n        const id = typeof options.id === 'string' ? options.id : ''\n        if (label === '' && id === '') continue\n        rows.push({\n          id: id || label,\n          order: typeof options.order === 'number' ? options.order : 0,\n          label: label || id,\n        })\n      }\n      rows.sort((a, b) => a.order - b.order)\n      return rows\n    }\n\n    /** 宿主目录；拿不到（宿主没有 /catalog 路由）就退回内置兜底清单。 */\n    function catalogPanels() {\n      if (state.catalog.panels.length > 0) return state.catalog.panels\n      if (state.catalog.ready) return []\n      return fallbackSections()\n    }\n\n    /**\n     * 分组来源：\n     * - sections：实时 slots 大类（含第三方插件注册的），用目录里的关键词 / 描述做补充；\n     *   slots 拿不到时退回目录里的官方大类。\n     * - cards：目录里的插件卡片（只在搜索时列）。\n     */\n    function panelSource() {\n      const catalog = catalogPanels()\n      const meta = new Map()\n      for (const panel of catalog) {\n        for (const title of [panel.name].concat(panel.titles || [])) {\n          if (!meta.has(title)) meta.set(title, panel)\n        }\n      }\n      const live = liveSections()\n      const sections = live.length > 0\n        ? live.map((row) => {\n            const known = meta.get(row.label) || meta.get(row.id)\n            return {\n              id: row.id,\n              kind: 'section',\n              name: row.label,\n              titles: known ? (known.titles || [known.name]) : [row.label],\n              keywords: (known && known.keywords ? known.keywords : []).concat(row.id === row.label ? [] : [row.id]),\n              description: known ? known.description : '',\n            }\n          })\n        : catalog.filter((panel) => panel.kind === 'section')\n      return {\n        sections,\n        cards: catalog.filter((panel) => panel.kind !== 'section'),\n      }\n    }\n\n    function matchesPanel(panel, query) {\n      return [panel.name].concat(panel.titles || [], panel.keywords || [], [panel.description]).join(' ').toLowerCase().includes(query)\n    }\n\n    /**\n     * 设置分组：本地过滤（零延迟）+ 服务端 panels 按 id / 标题去重补齐。\n     * 空查询只列设置一级大类（对齐桌面端搜索窗的「设置」组）。\n     */\n    function panelEntries(searching) {\n      const query = state.query.trim().toLowerCase()\n      const source = panelSource()\n      const pool = searching ? source.sections.concat(source.cards) : source.sections\n      const out = []\n      const seenIds = new Set()\n      const seenNames = new Set()\n      for (const panel of pool) {\n        if (searching && !matchesPanel(panel, query)) continue\n        const sectionIndex = panel.kind === 'section' ? source.sections.indexOf(panel) : -1\n        out.push(entryFromPanel(panel, searching, sectionIndex))\n        seenIds.add(panel.id)\n        seenNames.add(String(panel.name).toLowerCase())\n      }\n      if (searching) {\n        for (const panel of state.server.panels) {\n          if (seenIds.has(panel.id) || seenNames.has(String(panel.name).toLowerCase())) continue\n          out.push(entryFromPanel(panel, true, panel.kind === 'section' ? 0 : -1))\n        }\n      }\n      // 设置大类一条都不能少（第三方插件注册的也在里面），列表本来就可滚动\n      return out.slice(0, 14)\n    }\n\n    function matchesAction(action, query) {\n      if (query === '') return true\n      return [action.title].concat(action.keywords).some((text) => String(text).toLowerCase().includes(query))\n    }\n\n    /**\n     * 「最近」分组最多列几条。\n     *\n     * 早先空查询只放 4 条（怕「设置」大类被挤出首屏），真机反馈是**太少**——侧边栏里\n     * 明明有一屏会话，面板打开却只看到 4 条，还得再搜一次。列表本来就能滚（`.gs_list`\n     * 是 `overflow-y:auto`），所以这里放到 8 条：首屏仍是「最近 + 快捷操作」，\n     * 「设置」大类往下滚一格就到，换来的是打开面板就能看见一周内的会话。\n     *\n     * 上界与快捷键胶囊对齐：`⌥/Alt + 1…9` 只有 9 个数字键，再多也编不出快捷键。\n     */\n    const RECENT_SESSION_LIMIT = 8\n\n    /**\n     * 组装分组。空查询 = 「打开即有内容」的落地页（最近会话 + 快捷操作 + 设置）；\n     * 有查询 = 本地即时候选在前，宿主全文命中在后。\n     */\n    function buildGroups() {\n      const searching = state.query.trim() !== ''\n      const query = state.query.trim().toLowerCase()\n      const groups = []\n\n      const serverSessionIds = new Set(state.server.sessions.map((item) => item.id))\n      const recents = readSessionSummaries()\n        .filter((row) => !serverSessionIds.has(row.id))\n        .filter((row) => !searching || String(row.title).toLowerCase().includes(query))\n        .slice(0, RECENT_SESSION_LIMIT)\n\n      if (recents.length > 0) {\n        groups.push({\n          label: searching ? t('panel.recentSessions') : t('panel.recent'),\n          entries: recents.map((row, index) => ({\n            kind: 'session',\n            icon: 'chat',\n            title: highlightText(row.title, state.query),\n            meta: relativeTime(row.time),\n            chip: index < 9 ? ALT_LABEL + String(index + 1) : '',\n            payload: { id: row.id },\n          })),\n        })\n      }\n\n      if (searching && state.server.sessions.length > 0) {\n        groups.push({\n          label: t('panel.historySessions'),\n          entries: state.server.sessions.map((item) => ({\n            kind: 'session',\n            icon: 'chat',\n            title: highlightText(item.snippet || item.id, state.query),\n            meta: relativeTime(item.time),\n            payload: { id: item.id },\n          })),\n        })\n      }\n\n      if (searching && state.server.prompts.length > 0) {\n        groups.push({\n          label: 'Prompt',\n          entries: state.server.prompts.map((item) => ({\n            kind: 'prompt',\n            icon: 'file',\n            title: highlightText(item.name, state.query) + (item.active ? '<span class=\"gs_badge\">' + t('list.active') + '</span>' : ''),\n            subtitle: highlightText(item.snippet || item.description || '', state.query),\n            payload: { copy: item.snippet || item.description || '' },\n          })),\n        })\n      }\n\n      if (searching && state.server.tools.length > 0) {\n        groups.push({\n          label: t('panel.mcpTools'),\n          entries: state.server.tools.map((item) => ({\n            kind: 'tool',\n            icon: 'plug',\n            title: highlightText(item.name, state.query),\n            subtitle: item.description ? highlightText(item.description, state.query) : '',\n            meta: toolServerName(item.name),\n            payload: { name: item.name },\n          })),\n        })\n      }\n\n      const actions = QUICK_ACTIONS.filter((action) => {\n        try {\n          return action.available() && matchesAction(action, query)\n        } catch {\n          return false\n        }\n      })\n      if (actions.length > 0) {\n        groups.push({\n          label: t('panel.actions'),\n          entries: actions.map((action) => ({\n            kind: 'action',\n            icon: action.icon,\n            title: action.title,\n            chip: ALT_LABEL + action.chip,\n            payload: { actionId: action.id },\n          })),\n        })\n      }\n\n      const panels = panelEntries(searching)\n      if (panels.length > 0) groups.push({ label: t('panel.settings'), entries: panels })\n\n      return groups\n    }\n\n    /* ================================ 渲染 ================================ */\n\n    function rowHtml(entry, index) {\n      const iconHtml = entry.icon ? '<span class=\"gs_rowIcon\">' + (ICONS[entry.icon] || '') + '</span>' : ''\n      const metaHtml = entry.meta ? '<span class=\"gs_rowMeta\">' + esc(entry.meta) + '</span>' : ''\n      const chipHtml = entry.chip ? '<span class=\"gs_rowChip\">' + esc(entry.chip) + '</span>' : ''\n      const subHtml = entry.subtitle ? '<span class=\"gs_rowSub\">' + entry.subtitle + '</span>' : ''\n      return '<div class=\"gs_row\" role=\"option\" id=\"gs_opt_' + index + '\" data-index=\"' + index + '\" aria-selected=\"false\">' +\n        iconHtml +\n        '<span class=\"gs_rowMain\"><span class=\"gs_rowTitle\">' + entry.title + '</span>' + subHtml + '</span>' +\n        metaHtml + chipHtml +\n        '</div>'\n    }\n\n    function render() {\n      if (paletteEl === null) return\n      const list = listEl\n      if (list === null) return\n      const renderQuery = state.query.trim()\n      const groups = buildGroups()\n      currentEntries = []\n\n      // 重渲染会替换 DOM，旧的高亮引用失效：先清掉选中索引\n      activeItemIndex = -1\n\n      if (state.error !== '') {\n        list.innerHTML = '<div class=\"gs_error\">' + esc(state.error) + '</div>'\n        return\n      }\n\n      const parts = []\n      let index = 0\n      for (const group of groups) {\n        parts.push('<div class=\"gs_group\">')\n        if (group.label) parts.push('<div class=\"gs_groupLabel\">' + esc(group.label) + '</div>')\n        for (const entry of group.entries) {\n          currentEntries.push(entry)\n          parts.push(rowHtml(entry, index))\n          index += 1\n        }\n        parts.push('</div>')\n      }\n\n      if (state.loading) {\n        parts.push('<div class=\"gs_group\"><div class=\"gs_row gs_rowGhost\"><span class=\"gs_rowIcon\"><span class=\"gs_spinner\"></span></span><span class=\"gs_rowMain\"><span class=\"gs_rowTitle\">' + t('list.searching') + '</span></span></div></div>')\n      }\n\n      if (currentEntries.length === 0 && !state.loading) {\n        list.innerHTML = '<div class=\"gs_hint\">' + (renderQuery === ''\n          ? t('list.hintEmpty') + '<br />' + t('list.hintKeys')\n          : t('list.empty')) + '</div>'\n        return\n      }\n\n      list.innerHTML = parts.join('')\n      list.querySelectorAll('.gs_row[data-index]').forEach((el) => {\n        const itemIndex = Number(el.dataset.index)\n        el.addEventListener('click', () => activateEntry(currentEntries[itemIndex]))\n        el.addEventListener('mousemove', () => {\n          if (activeItemIndex !== itemIndex) setActiveItem(itemIndex)\n        })\n      })\n      // 默认选中首项：回车即打开（命令面板的通用手感）\n      if (currentEntries.length > 0) setActiveItem(0)\n    }\n\n    function setActiveItem(index) {\n      if (listEl === null) return\n      const rows = listEl.querySelectorAll('.gs_row[data-index]')\n      rows.forEach((row) => {\n        const rowIndex = Number(row.dataset.index)\n        if (rowIndex === index) {\n          row.setAttribute('data-active', '')\n          row.setAttribute('aria-selected', 'true')\n        } else {\n          row.removeAttribute('data-active')\n          row.setAttribute('aria-selected', 'false')\n        }\n      })\n      activeItemIndex = index\n      const active = rows[index]\n      if (active === undefined) return\n      if (inputEl !== null) inputEl.setAttribute('aria-activedescendant', 'gs_opt_' + String(index))\n      try {\n        active.scrollIntoView({ block: 'nearest' })\n      } catch {\n        /* 滚动失败不阻塞 */\n      }\n    }\n\n    function moveActiveItem(delta) {\n      if (currentEntries.length === 0) return\n      const next = activeItemIndex < 0\n        ? (delta > 0 ? 0 : currentEntries.length - 1)\n        : Math.min(currentEntries.length - 1, Math.max(0, activeItemIndex + delta))\n      setActiveItem(next)\n    }\n\n    /* ================================ 打开条目 ================================ */\n\n    /**\n     * 打开会话 = 一次**视图导航**。\n     *\n     * DSH 0.1.6 把视图选中项搬出了会话域（会话控制器自己的注释：「view selection remains\n     * outside the Controller」），`sessions.open()` 也随之从契约里消失——命令面板于是\n     * 全部走「当前环境无法直接打开会话」那条 toast，点会话没反应且看不出为什么。\n     * 新宿主用 `uiWorkspace.openSession(target)`；老宿主（≤0.1.5）仍只有 `sessions.open`。\n     */\n    function openSession(id) {\n      const query = state.query\n      const uiWorkspace = uiWorkspaceService()\n      const sessions = activeCtx && activeCtx.sessions\n      const canOpenViaWorkspace = uiWorkspace !== undefined && typeof uiWorkspace.openSession === 'function'\n      const canOpenViaSessions = sessions !== undefined && sessions !== null && typeof sessions.open === 'function'\n      if (!canOpenViaWorkspace && !canOpenViaSessions) {\n        toast(t('error.openSessionUnavailable'), 'error')\n        return\n      }\n      try {\n        if (canOpenViaWorkspace) uiWorkspace.openSession(id)\n        else sessions.open(id)\n        closePalette()\n        jumpToSessionText(query)\n      } catch (error) {\n        toast(error && error.message ? error.message : t('error.openSession'), 'error')\n      }\n    }\n\n    async function activateEntry(entry) {\n      if (!entry) return\n      if (entry.kind === 'session') {\n        openSession(entry.payload.id)\n        return\n      }\n      if (entry.kind === 'action') {\n        const action = QUICK_ACTIONS.find((item) => item.id === entry.payload.actionId)\n        closePalette()\n        if (action) await action.run()\n        return\n      }\n      if (entry.kind === 'prompt') {\n        const copy = entry.payload.copy\n        closePalette()\n        const jumped = await openSettingsCard(['Prompt 管理', 'Prompt Management'])\n        if (jumped) {\n          toast(t('msg.openedCard', { name: t('card.prompt') }), 'ok')\n        } else {\n          copyText(copy)\n        }\n        return\n      }\n      if (entry.kind === 'tool') {\n        const name = entry.payload.name\n        closePalette()\n        const jumped = await openSettingsCard(['MCP 服务器配置', 'MCP Server Configuration'])\n        if (jumped) {\n          toast(t('msg.openedCard', { name: t('card.mcp') }), 'ok')\n        } else {\n          copyText(name)\n        }\n        return\n      }\n      if (entry.kind === 'panel') {\n        const isSection = entry.payload.section === true\n        const titles = entry.payload.titles\n        const label = titles[0] || t('panel.untitled')\n        closePalette()\n        const jumped = isSection ? await openSettingsSection(titles, entry.payload.index) : await openSettingsCard(titles)\n        if (jumped) {\n          toast(isSection ? t('msg.openedSection', { name: label }) : t('msg.openedCard', { name: label }), 'ok')\n        } else {\n          copyText(label)\n        }\n      }\n    }\n\n    function copyText(text) {\n      if (!text) return\n      const done = () => toast(t('msg.copied'), 'ok')\n      const fail = () => toast(t('error.copyFailed'), 'error')\n      if (navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {\n        navigator.clipboard.writeText(text).then(done, fail)\n      } else {\n        try {\n          const textarea = document.createElement('textarea')\n          textarea.value = text\n          document.body.appendChild(textarea)\n          textarea.select()\n          document.execCommand('copy')\n          textarea.remove()\n          done()\n        } catch {\n          fail()\n        }\n      }\n    }\n\n    /* ================================ 查询 ================================ */\n\n    async function runSearch() {\n      const query = state.query.trim()\n      const seq = ++searchSeq\n      if (query === '') {\n        state.server = { sessions: [], prompts: [], tools: [], panels: [] }\n        state.error = ''\n        state.loading = false\n        render()\n        return\n      }\n      // 取消上一个仍在途的请求，避免服务器端堆积扫描\n      activeCtl?.abort()\n      const controller = new AbortController()\n      activeCtl = controller\n      // 最少 2 个字符才发起查询（按码点计，CJK 单字不触发全量扫描）\n      if ([...query].length < 2) {\n        state.server = { sessions: [], prompts: [], tools: [], panels: [] }\n        state.error = ''\n        state.loading = false\n        render()\n        return\n      }\n      state.loading = true\n      state.error = ''\n      render()\n      try {\n        const data = await api('/api/dsh-search/query?q=' + encodeURIComponent(query), controller.signal)\n        if (seq !== searchSeq) return\n        state.server = {\n          sessions: data.sessions || [],\n          prompts: data.prompts || [],\n          tools: data.tools || [],\n          panels: data.panels || [],\n        }\n      } catch (error) {\n        if (seq !== searchSeq) return\n        if (error && error.name === 'AbortError') return\n        state.error = error.message || String(error)\n        state.server = { sessions: [], prompts: [], tools: [], panels: [] }\n      } finally {\n        if (seq === searchSeq) {\n          state.loading = false\n          render()\n        }\n      }\n    }\n\n    /* ================================ 面板开关 ================================ */\n\n    function subscribeSessionStore() {\n      if (sessionUnsubscribe !== null) return\n      const sessions = activeCtx && activeCtx.sessions\n      const store = sessions && sessions.list\n      if (!store || typeof store.subscribe !== 'function') return\n      try {\n        sessionUnsubscribe = store.subscribe(() => {\n          // 回调可能在渲染中途触发：下一次任务再重绘\n          if (sessionRenderTimer !== null) return\n          sessionRenderTimer = setTimeout(() => {\n            sessionRenderTimer = null\n            if (paletteEl !== null) render()\n          }, 0)\n        })\n      } catch {\n        sessionUnsubscribe = null\n      }\n    }\n\n    function unsubscribeSessionStore() {\n      if (sessionUnsubscribe !== null) {\n        try {\n          sessionUnsubscribe()\n        } catch {\n          /* 释放失败不阻塞 */\n        }\n        sessionUnsubscribe = null\n      }\n      if (sessionRenderTimer !== null) {\n        clearTimeout(sessionRenderTimer)\n        sessionRenderTimer = null\n      }\n    }\n\n    function focusInput() {\n      if (inputEl === null) return\n      try {\n        inputEl.focus()\n      } catch {\n        /* 聚焦失败不阻塞 */\n      }\n    }\n\n    function openPalette() {\n      if (paletteEl !== null && paletteEl.isConnected) {\n        focusInput()\n        return\n      }\n      state.query = ''\n      state.server = { sessions: [], prompts: [], tools: [], panels: [] }\n      state.error = ''\n      state.loading = false\n      activeItemIndex = -1\n\n      const backdrop = document.createElement('div')\n      backdrop.className = 'gs_backdrop'\n      backdrop.addEventListener('mousedown', (event) => {\n        if (event.target === backdrop) closePalette()\n      })\n\n      const panel = document.createElement('div')\n      panel.className = 'gs_palette'\n      panel.setAttribute('role', 'dialog')\n      panel.setAttribute('aria-modal', 'true')\n      panel.setAttribute('aria-label', t('card.name'))\n      panel.innerHTML =\n        '<div class=\"gs_inputRow\">' +\n          '<span class=\"gs_inputIcon\">' + ICONS.search + '</span>' +\n          '<input class=\"gs_input\" type=\"text\" role=\"combobox\" aria-autocomplete=\"list\" aria-expanded=\"true\" aria-controls=\"gs_list\" placeholder=\"' + esc(t('placeholder.panel')) + '\" autocomplete=\"off\" spellcheck=\"false\" />' +\n        '</div>' +\n        '<div class=\"gs_list\" id=\"gs_list\" role=\"listbox\" aria-label=\"' + esc(t('panel.results')) + '\"></div>' +\n        '<div class=\"gs_footer\">' +\n          '<span class=\"gs_footerItem\"><kbd class=\"gs_key\">↑</kbd><kbd class=\"gs_key\">↓</kbd>' + t('panel.hintSelect') + '</span>' +\n          '<span class=\"gs_footerItem\"><kbd class=\"gs_key\">↵</kbd>' + t('panel.hintOpen') + '</span>' +\n          '<span class=\"gs_footerItem\"><kbd class=\"gs_key\">esc</kbd>' + t('panel.hintClose') + '</span>' +\n        '</div>'\n\n      backdrop.appendChild(panel)\n      document.body.appendChild(backdrop)\n      paletteEl = backdrop\n      listEl = panel.querySelector('.gs_list')\n      inputEl = panel.querySelector('.gs_input')\n      lastFocused = document.activeElement\n\n      inputEl.addEventListener('input', () => {\n        state.query = inputEl.value\n        // 本地候选零延迟重绘；宿主全文命中防抖后补齐\n        render()\n        clearTimeout(searchTimer)\n        searchTimer = setTimeout(runSearch, 220)\n      })\n      inputEl.addEventListener('keydown', (event) => {\n        if (event.isComposing) return\n        if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {\n          event.preventDefault()\n          moveActiveItem(event.key === 'ArrowDown' ? 1 : -1)\n          return\n        }\n        if (event.key === 'Enter') {\n          event.preventDefault()\n          const entry = activeItemIndex >= 0 ? currentEntries[activeItemIndex] : undefined\n          if (entry !== undefined) {\n            activateEntry(entry)\n            return\n          }\n          clearTimeout(searchTimer)\n          runSearch()\n        }\n      })\n      // 点空白处不丢焦点：保持键盘可用\n      panel.addEventListener('mousedown', (event) => {\n        if (event.target === panel) event.preventDefault()\n      })\n\n      setTimeout(focusInput, 0)\n      render()\n      loadCatalog()\n      subscribeSessionStore()\n    }\n\n    function closePalette() {\n      if (paletteEl === null) return\n      activeCtl?.abort()\n      activeCtl = null\n      clearTimeout(searchTimer)\n      unsubscribeSessionStore()\n      paletteEl.remove()\n      paletteEl = null\n      listEl = null\n      inputEl = null\n      activeItemIndex = -1\n      currentEntries = []\n      // 还原焦点，但绝不还给侧边栏入口：入口的 focusin 会立刻把面板重新打开，\n      // 表现为「点不掉」。顺手在极短窗口内屏蔽入口的 focusin。\n      const restoreTarget = lastFocused\n      lastFocused = null\n      entryFocusMutedUntil = Date.now() + 250\n      if (restoreTarget && typeof restoreTarget.focus === 'function' && document.contains(restoreTarget) && !insideSearchEntry(restoreTarget)) {\n        try {\n          restoreTarget.focus()\n        } catch {\n          /* 还原焦点失败不阻塞 */\n        }\n      }\n    }\n\n    /* ---------- 键盘：全局快捷键 ---------- */\n\n    /**\n     * 全局（capture 阶段）按键：\n     *   ⌘/Ctrl+K 开关面板；esc 关闭；\n     *   ⌥/Alt+数字 打开第 N 条「最近会话」；⌥/Alt+N / O / , 触发对应快捷操作。\n     * 用 event.code 判定（macOS 上 ⌥+数字/字母会变成特殊字符，key 不可靠）。\n     */\n    function onGlobalKeydown(event) {\n      if (event.isComposing) return\n      if ((event.metaKey || event.ctrlKey) && !event.altKey && String(event.key).toLowerCase() === 'k') {\n        event.preventDefault()\n        event.stopPropagation()\n        if (paletteEl !== null && paletteEl.isConnected) focusInput()\n        else openPalette()\n        return\n      }\n      if (paletteEl === null || !paletteEl.isConnected) return\n      if (event.key === 'Escape') {\n        event.preventDefault()\n        closePalette()\n        return\n      }\n      if (!event.altKey || event.metaKey || event.ctrlKey) return\n      const digit = /^Digit([1-9])$/.exec(event.code || '')\n      if (digit !== null) {\n        const entry = currentEntries[Number(digit[1]) - 1]\n        if (entry !== undefined) {\n          event.preventDefault()\n          activateEntry(entry)\n        }\n        return\n      }\n      const code = String(event.code || '')\n      const hit = code === 'Comma'\n        ? QUICK_ACTIONS.find((action) => action.chip === ',')\n        : QUICK_ACTIONS.find((action) => action.code === code)\n      if (hit !== undefined && hit.available()) {\n        event.preventDefault()\n        closePalette()\n        hit.run()\n      }\n    }\n\n    /* ================================ 跳转到设置 ================================ */\n\n    function waitFor(predicate, timeout = 4000) {\n      return new Promise((resolve) => {\n        const startedAt = Date.now()\n        const timer = setInterval(() => {\n          let value\n          try {\n            value = predicate()\n          } catch {\n            value = null\n          }\n          if (value) {\n            clearInterval(timer)\n            resolve(value)\n            return\n          }\n          if (Date.now() - startedAt > timeout) {\n            clearInterval(timer)\n            resolve(null)\n          }\n        }, 60)\n      })\n    }\n\n    /**\n     * 设置入口有两代形态，**0.2.1 换了**（真机实测，2026-10-20）。\n     *\n     * - DSH ≤0.2.0：侧边栏底部是设置 shell 自己的触发器 `button[aria-haspopup=\"dialog\"]`，\n     *   点一下直接开设置窗。\n     * - DSH ≥0.2.1：`settings.launcher` 这个单值槽被账号菜单占住（`ui-settings-account` 的\n     *   AccountMenu），于是侧边栏底部那个按钮变成 `aria-haspopup=\"menu\"`、可访问名「账号菜单」，\n     *   **设置窗是菜单里的第一项**（「设置 ⌥⌘,」）。这时整页 `button[aria-haspopup=\"dialog\"]`\n     *   的个数是 **0**——旧实现据此判「当前环境无法打开设置」，所有设置跳转于是全部退化成\n     *   「把条目名复制到剪贴板」，用户看到的就是「点了没反应」。\n     *\n     * 所以入口判定必须是三档：宿主命令（不依赖 DOM 形态）→ dialog 触发器（老宿主）→\n     * 账号菜单里的「设置」项（新宿主）。\n     */\n    const SETTINGS_MENU_LABELS = ['设置', 'Settings']\n    const ACCOUNT_MENU_LABELS = ['账号菜单', 'Account menu', '账户菜单']\n\n    /** 设置窗本体。宿主给它标了 `data-shortcut-modal=\"settings\"`（快捷键模态判定用的同一标记）。 */\n    function settingsDialogEl() {\n      return document.querySelector('[role=\"dialog\"][data-shortcut-modal=\"settings\"]')\n        || document.querySelector('[data-shortcut-modal=\"settings\"]')\n    }\n\n    function sidebarScope() {\n      return document.querySelector('[data-pane=\"sidebar\"], [class*=\"sidebarCol\"]') || document\n    }\n\n    /** 老宿主（≤0.2.0）的直连触发器。 */\n    function findSettingsDialogTrigger() {\n      const scope = sidebarScope()\n      return scope.querySelector('button[aria-haspopup=\"dialog\"]') || document.querySelector('button[aria-haspopup=\"dialog\"]')\n    }\n\n    /** 新宿主（≥0.2.1）的账号菜单按钮：侧边栏底部、`aria-haspopup=\"menu\"`、可访问名「账号菜单」。 */\n    function findAccountMenuTrigger() {\n      const candidates = [...sidebarScope().querySelectorAll('button[aria-haspopup=\"menu\"]')]\n      for (const label of ACCOUNT_MENU_LABELS) {\n        const hit = candidates.find((btn) => (btn.getAttribute('aria-label') || '').trim() === label)\n        if (hit !== undefined) return hit\n      }\n      // 宿主换了可访问名时按位置兜底：侧边栏里最后一个菜单按钮就是底部那一行（账号菜单在 footArea）。\n      return candidates.length > 0 ? candidates[candidates.length - 1] : null\n    }\n\n    /** 菜单项按文本找（菜单是 portal 到 body 的，所以整页找）。 */\n    function findMenuItem(texts, scope) {\n      const root = scope || document\n      for (const item of root.querySelectorAll('[role=\"menuitem\"], [role=\"menuitemradio\"]')) {\n        const text = (item.textContent || '').replace(/\\s+/g, ' ').trim()\n        if (text !== '' && texts.some((label) => text.startsWith(label) || text.includes(label))) return item\n      }\n      return null\n    }\n\n    /** 宿主注册的 `shortcuts` 服务（0.2.1 起官方有 `settings.open` 命令，最稳的一条路）。 */\n    function shortcutsService() {\n      try {\n        const ctx = activeCtx\n        if (!ctx) return undefined\n        const service = typeof ctx.get === 'function' ? ctx.get('shortcuts') : ctx.shortcuts\n        return service !== undefined && service !== null ? service : undefined\n      } catch {\n        return undefined\n      }\n    }\n\n    /**\n     * 走宿主的 `settings.open` 命令开设置窗。\n     * 设置窗已开时**不能**调用：那条命令的 resolve 在 `modal === \"settings\"` 时是「关掉最上层模态」。\n     */\n    function invokeSettingsCommand() {\n      const service = shortcutsService()\n      const registry = service === undefined ? undefined : service.registry\n      if (registry === undefined || registry === null || typeof registry.invoke !== 'function') return false\n      if (settingsDialogEl() !== null) return false\n      try {\n        registry.invoke('settings.open', { modal: null, region: 'page', target: document.body })\n        return true\n      } catch {\n        return false\n      }\n    }\n\n    /** 新宿主：点开账号菜单 → 点「设置」。开错了菜单就原样收起，不把别人的菜单留在屏幕上。 */\n    async function openSettingsViaAccountMenu() {\n      const trigger = findAccountMenuTrigger()\n      if (trigger === null) return false\n      const wasOpen = trigger.getAttribute('aria-expanded') === 'true'\n      if (!wasOpen) trigger.click()\n      const entry = await waitFor(() => findMenuItem(SETTINGS_MENU_LABELS))\n      if (entry === null) {\n        if (!wasOpen) {\n          try {\n            trigger.click()\n          } catch {\n            /* 收不起来也不阻塞：下一次打开设置会重试 */\n          }\n        }\n        return false\n      }\n      entry.click()\n      return (await waitFor(() => settingsDialogEl())) !== null\n    }\n\n    /** 打开设置窗并返回它（已经开着就直接返回）。三档入口见上面的注释。 */\n    async function openSettingsDialog() {\n      const existing = settingsDialogEl()\n      if (existing !== null) return existing\n      if (invokeSettingsCommand()) {\n        const opened = await waitFor(() => settingsDialogEl())\n        if (opened !== null) return opened\n      }\n      const trigger = findSettingsDialogTrigger()\n      if (trigger !== null) {\n        if (trigger.getAttribute('aria-expanded') !== 'true') trigger.click()\n        const opened = await waitFor(() => settingsDialogEl())\n        if (opened !== null) return opened\n      }\n      if (await openSettingsViaAccountMenu()) return settingsDialogEl()\n      return null\n    }\n\n    /** 「打开设置」这条快捷操作是否可用（入口形态与语言无关，只看有没有一条能走的路）。 */\n    function settingsEntryAvailable() {\n      return settingsDialogEl() !== null\n        || findSettingsDialogTrigger() !== null\n        || findAccountMenuTrigger() !== null\n        || shortcutsService() !== undefined\n    }\n\n    function findButtonByText(selector, texts, scope) {\n      const root = scope || document\n      const candidates = root.querySelectorAll(selector)\n      for (const el of candidates) {\n        const text = (el.textContent || '').replace(/\\s+/g, ' ').trim()\n        if (texts.some((item) => text.includes(item))) return el\n      }\n      return null\n    }\n\n    function findSettingsSectionButton(scope) {\n      return findNavSectionButton(['插件', 'Plugins'], scope)\n    }\n\n    /**\n     * 在设置窗口侧边栏找到目标一级大类的导航按钮。\n     * 先按标题文本打分（精确 > 前缀 > 包含），全不命中时退回「注册顺序第 index 个」——\n     * 第三方大类的本地化标题与注册 label 万一不一致，靠顺序也能定位。\n     */\n    function findNavSectionButton(titleTexts, scope, index) {\n      const root = (scope && scope.tagName === 'NAV' ? scope : (scope?.querySelector('nav') || scope)) || document\n      const wanted = (titleTexts || []).filter((item) => item)\n      const buttons = []\n      for (const btn of root.querySelectorAll('button')) {\n        const text = (btn.textContent || '').replace(/\\s+/g, ' ').trim()\n        const looksLikeNav = /sidebar-nav|section|nav/i.test(btn.className) || btn.closest('nav') !== null || btn.hasAttribute('aria-current') || btn.getAttribute('role') === 'tab'\n        if (!looksLikeNav || text === '') continue\n        buttons.push({ btn, text })\n      }\n      let best = null\n      let bestScore = 0\n      for (const candidate of buttons) {\n        for (const item of wanted) {\n          const score = candidate.text === item\n            ? 4\n            : (candidate.text.startsWith(item) || item.startsWith(candidate.text) ? 3 : (candidate.text.includes(item) ? 2 : (item.includes(candidate.text) ? 1 : 0)))\n          if (score > bestScore) {\n            bestScore = score\n            best = candidate.btn\n          }\n        }\n      }\n      if (best !== null && bestScore >= 2) return best\n      if (typeof index === 'number' && index >= 0 && index < buttons.length) return buttons[index].btn\n      return best\n    }\n\n    /** 打开设置对话框并导航到指定一级大类（侧边栏 nav 按钮）。 */\n    async function openSettingsSection(titleTexts, index) {\n      const panel = await openSettingsDialog()\n      if (panel === null) {\n        console.warn('[dsh-global-search] openSettingsSection: settings dialog not found')\n        return false\n      }\n      let sectionButton = await waitFor(() => findNavSectionButton(titleTexts, panel, index))\n      if (sectionButton === null) {\n        sectionButton = await waitFor(() => findButtonByText('button', titleTexts, panel.querySelector('nav') || panel))\n      }\n      if (sectionButton === null) {\n        console.warn('[dsh-global-search] openSettingsSection: nav section not found: ' + titleTexts.join(' / '))\n        return false\n      }\n      sectionButton.click()\n      try {\n        sectionButton.scrollIntoView({ block: 'center', behavior: 'smooth' })\n      } catch {\n        /* 滚动失败不阻塞 */\n      }\n      return true\n    }\n\n    function findCardHeader(titleTexts, scope) {\n      const root = scope || document\n      const buttons = root.querySelectorAll('button')\n      for (const btn of buttons) {\n        const text = (btn.textContent || '').replace(/\\s+/g, ' ').trim()\n        const looksLikeCardHeader = btn.hasAttribute('aria-expanded') || /cardHeader|header/i.test(btn.className)\n        if (looksLikeCardHeader && titleTexts.some((item) => text.includes(item))) return btn\n      }\n      return null\n    }\n\n    /**\n     * 命令面板里的「设置卡片」条目如何落到真实界面。\n     *\n     * DSH ≤0.1.5：插件的设置卡片在 **设置 → 插件 → 插件配置** 标签页里，按卡片标题点开折叠。\n     * DSH ≥0.1.6-alpha.2：配置搬到了**侧边栏「插件」页**（ui-plugin-manager）——每个插件是一条\n     * bundle 行，点进该插件后，行的「配置」入口（aria-label=\"配置 <行 id>\"）打开配置页。\n     * 因此先走新路径，失败再退回旧路径，两代都能跳。\n     */\n\n    /** 命令面板条目标题 → 插件管理页里的插件短名。 */\n    const PLUGIN_MANAGER_IDS = [\n      ['MCP 服务器配置', 'mcp'],\n      ['Prompt 管理', 'prompt'],\n      ['环境变量 / 密钥管理', 'env'],\n      ['Profile 管理', 'profile'],\n      ['RSS / 新闻聚合', 'rss'],\n      ['Codegraph 集成', 'codegraph'],\n      ['Docker 容器面板', 'docker'],\n    ]\n\n    /** 文本**完全相等**的按钮（findButtonByText 是 includes，短名会误配，这里要精确）。 */\n    function findExactButton(texts, scope) {\n      const root = scope || document\n      for (const btn of root.querySelectorAll('button')) {\n        const text = (btn.textContent || '').replace(/\\s+/g, ' ').trim()\n        if (text !== '' && texts.some((item) => text === item)) return btn\n      }\n      return null\n    }\n\n    /** 侧边栏一级入口（新版的「插件」页就在侧边栏，与终端 / 容器同级）。 */\n    function findSidebarEntry(texts) {\n      const scope = document.querySelector('[data-pane=\"sidebar\"], [class*=\"sidebar\"]') || document\n      return findExactButton(texts, scope) || findExactButton(texts, document)\n    }\n\n    /** 走 DSH ≥0.1.6 的侧边栏「插件」页打开某个插件的配置页。 */\n    async function openPluginManagerCard(titleTexts) {\n      const id = PLUGIN_MANAGER_IDS.find(([title]) => titleTexts.includes(title))\n      const entry = findSidebarEntry(['插件', 'Plugins'])\n      if (entry === null && id === undefined) return false\n      if (entry !== null) {\n        entry.click()\n        const ready = await waitFor(() => {\n          const text = document.body.textContent || ''\n          return text.includes('添加插件') || text.includes('Add plugin')\n        })\n        if (ready === null) return false\n      }\n      if (id === undefined) return false\n      const pkg = await waitFor(() => findExactButton([id[1]]))\n      if (pkg === null) return false\n      pkg.click()\n      const configure = await waitFor(() => (\n        document.querySelector('[aria-label^=\"配置 \"]') || document.querySelector('[aria-label^=\"Configure \"]')\n      ))\n      if (configure === null) return false\n      configure.click()\n      return true\n    }\n\n    async function openSettingsCard(titleTexts) {\n      if (await openPluginManagerCard(titleTexts)) return true\n\n      const panel = await openSettingsDialog()\n      if (panel === null) {\n        console.warn('[dsh-global-search] openSettingsCard: settings dialog not found')\n        return false\n      }\n\n      let sectionButton = await waitFor(() => findSettingsSectionButton(panel))\n      if (sectionButton === null) {\n        sectionButton = await waitFor(() => findButtonByText('button', ['插件', 'Plugins'], panel.querySelector('nav') || panel))\n      }\n      if (sectionButton === null) {\n        console.warn('[dsh-global-search] openSettingsCard: plugins section not found')\n        return false\n      }\n      sectionButton.click()\n\n      let tab = await waitFor(() => findButtonByText('button[role=\"tab\"]', ['插件配置', 'Plugin configuration'], panel))\n      if (tab === null) {\n        tab = await waitFor(() => findButtonByText('button', ['插件配置', 'P